window.CS50KZ_MATH_EXAM.diffcalc = [{"id":"m4-1-direct:0","l":1,"lvl":"easy","type":"num","ctx":"Көпмүшеліктің шегі. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to2}(3x^2-2x+1)$","a":9},{"id":"m4-1-direct:1","l":1,"lvl":"easy","type":"num","ctx":"Көпмүшеліктің шегі. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to-1}\\dfrac{x^2+3}{x+3}$","a":2},{"id":"m4-1-tf:0","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер $f(a)$ анықталмаған болса, $\\lim_{x\\to a}f(x)$ бола алмайды.","a":false,"e":"Жалған: шек нүктенің өзіндегі мәнге тәуелді емес. $\\dfrac{x^2-1}{x-1}$ үшін $f(1)$ жоқ, бірақ шек 2."},{"id":"m4-1-tf:1","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\lim_{x\\to a}f(x)=L$ болса, $f(a)=L$ болуы керек.","a":false,"e":"Жалған: $f(a)$ басқа сан болуы мүмкін не мүлде болмауы мүмкін. Тең болғанда ғана функция $a$ нүктесінде үзіліссіз."},{"id":"m4-1-tf:2","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Шек жалғыз: бір нүктеде функцияның екі әртүрлі шегі бола алмайды.","a":true,"e":"Ақиқат: Теорема 1.2, 3-қорыту."},{"id":"m4-1-tf:3","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"Егер сол және оң жақты шектер бар болса, онда екі жақты шек те бар.","a":false,"e":"Жалған: олар тең болғанда ғана. $\\frac{|x|}{x}$ үшін нөлде олар $-1$ және $1$."},{"id":"m4-1-tf:4","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\lim_{x\\to0}\\dfrac1{x^2}=+\\infty$.","a":true,"e":"Ақиқат: $x$ екі жақтан да нөлге жақындағанда $x^2$ оң және нөлге ұмтылады, сондықтан $\\frac1{x^2}$ шексіз өседі."},{"id":"m4-1-pick:0","l":1,"lvl":"easy","type":"choice","ctx":"Шекті анықтамамен байланыстыру. Дұрыс жауапты таңдаңыз. Екінші сұрақта бірнеше жауап дұрыс болуы мүмкін.","q":"$\\varepsilon$-$\\delta$ анықтамасында $\\delta$ нені білдіреді?","o":["$x$-тің $a$-дан рұқсат етілген ең үлкен ауытқуы","$f(x)$-тің $L$-ден рұқсат етілген ауытқуы","$f$ функциясының туындысы","нүктедегі функцияның мәні"],"a":0,"e":"$\\delta$ - аргументтің $a$-дан қашықтығына қойылатын шек, ал $\\varepsilon$ - мәннің $L$-ден ауытқуы."},{"id":"m4-1-pick:1","l":1,"lvl":"easy","type":"choice","ctx":"Шекті анықтамамен байланыстыру. Дұрыс жауапты таңдаңыз. Екінші сұрақта бірнеше жауап дұрыс болуы мүмкін.","q":"Төмендегі функциялардың қайсысының $x\\to0$ кезінде ақырлы шегі бар?","o":["$x^2+5$","$\\dfrac{1}{x}$","$\\sin\\dfrac{1}{x}$","$x\\sin\\dfrac{1}{x}$","$\\dfrac{|x|}{x}$"],"a":[0,3],"e":"$x^2+5\\to5$; $x\\sin\\frac1x\\to0$ (қысу). $\\frac1x$ шексіздікке кетеді (екі жағы әртүрлі), $\\sin\\frac1x$ тербеледі, $\\frac{|x|}{x}$ секіреді."},{"id":"m4-1-holes:0","l":1,"lvl":"easy","type":"num","ctx":"Көбейткішті қысқартып шек табу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to3}\\dfrac{x^2-9}{x-3}$","a":6},{"id":"m4-1-holes:1","l":1,"lvl":"easy","type":"num","ctx":"Көбейткішті қысқартып шек табу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to-2}\\dfrac{x^2+5x+6}{x+2}$","a":1},{"id":"m4-1-graph:0","l":1,"lvl":"medium","type":"choice","ctx":"Графиктен шек оқу. Функцияның графигі былай сипатталған: $x<2$ үшін $y=x+1$ түзуі (нүкте $(2;3)$ тесік); $x>2$ үшін $y=7-x$ түзуі, ал $x=2$ нүктесінде функция $y=0$ мәнін қабылдайды. Сұрақтарға жауап беріңіз.","q":"$\\lim_{x\\to2^-}f(x)$ неге тең?","o":["$3$","$5$","$0$","жоқ"],"a":0,"e":"Сол жақта $f=x+1\\to3$."},{"id":"m4-1-graph:1","l":1,"lvl":"medium","type":"choice","ctx":"Графиктен шек оқу. Функцияның графигі былай сипатталған: $x<2$ үшін $y=x+1$ түзуі (нүкте $(2;3)$ тесік); $x>2$ үшін $y=7-x$ түзуі, ал $x=2$ нүктесінде функция $y=0$ мәнін қабылдайды. Сұрақтарға жауап беріңіз.","q":"$\\lim_{x\\to2^+}f(x)$ неге тең?","o":["$3$","$5$","$0$","жоқ"],"a":1,"e":"Оң жақта $f=7-x\\to5$."},{"id":"m4-1-graph:2","l":1,"lvl":"medium","type":"choice","ctx":"Графиктен шек оқу. Функцияның графигі былай сипатталған: $x<2$ үшін $y=x+1$ түзуі (нүкте $(2;3)$ тесік); $x>2$ үшін $y=7-x$ түзуі, ал $x=2$ нүктесінде функция $y=0$ мәнін қабылдайды. Сұрақтарға жауап беріңіз.","q":"$\\lim_{x\\to2}f(x)$ және $f(2)$ туралы дұрыс пікір.","o":["Шек 3, мән 0","Шек жоқ, мән 0","Шек 5, мән 0","Шек 0, мән 0"],"a":1,"e":"Бір жақты шектер ($3$ және $5$) әртүрлі, сондықтан шек жоқ; $f(2)=0$ қолмен берілген мән, ол шекке әсер етпейді."},{"id":"m4-1-onesided:0","l":1,"lvl":"medium","type":"num","ctx":"Бөлікті функцияның бір жақты шектері. $f(x)=\\begin{cases}x^2-1,&x<2\\\\ 5-x,&x\\ge2\\end{cases}$ функциясы берілген.","q":"$\\lim_{x\\to2^-}f(x)=\\ ?$","a":3},{"id":"m4-1-onesided:1","l":1,"lvl":"medium","type":"num","ctx":"Бөлікті функцияның бір жақты шектері. $f(x)=\\begin{cases}x^2-1,&x<2\\\\ 5-x,&x\\ge2\\end{cases}$ функциясы берілген.","q":"$\\lim_{x\\to2^+}f(x)=\\ ?$","a":3},{"id":"m4-1-onesided:2","l":1,"lvl":"medium","type":"num","ctx":"Бөлікті функцияның бір жақты шектері. $f(x)=\\begin{cases}x^2-1,&x<2\\\\ 5-x,&x\\ge2\\end{cases}$ функциясы берілген.","q":"$\\lim_{x\\to2}f(x)=\\ ?$ (шек бар болса, оның мәнін жазыңыз)","a":3},{"id":"m4-1-delta:0","l":1,"lvl":"medium","type":"expr","ctx":"δ-ны ε арқылы өрнектеу. Мұнда $\\varepsilon$ орнына латын t әрпін жазыңыз (мысалы, t/3 ). Өрнек $\\varepsilon$ арқылы жазылған ең үлкен қолайлы $\\delta$ болуы тиіс.","q":"$\\lim_{x\\to1}(5x-2)=3$. Ең үлкен жарамды $\\delta(\\varepsilon)=\\ ?$ ($\\varepsilon$ орнына $t$)","a":"t/5","vars":["t"],"dom":[0.1,3]},{"id":"m4-1-delta:1","l":1,"lvl":"medium","type":"expr","ctx":"δ-ны ε арқылы өрнектеу. Мұнда $\\varepsilon$ орнына латын t әрпін жазыңыз (мысалы, t/3 ). Өрнек $\\varepsilon$ арқылы жазылған ең үлкен қолайлы $\\delta$ болуы тиіс.","q":"$\\lim_{x\\to2}(-4x+1)=-7$. Ең үлкен жарамды $\\delta(\\varepsilon)=\\ ?$","a":"t/4","vars":["t"],"dom":[0.1,3]},{"id":"m4-1-nbhd:0","l":1,"lvl":"medium","type":"interval","ctx":"ε-маңай аралығы. Аралықты жазыңыз: шексіздік - oo, бірігу - U.","q":"$f(x)=2x-1$, $L=5$ (шек $x\\to3$ кезінде). $|f(x)-5|< 0{,}4$ теңсіздігін қанағаттандыратын барлық $x$ жиынын табыңыз.","a":"(2.8; 3.2)"},{"id":"m4-1-nbhd:1","l":1,"lvl":"medium","type":"interval","ctx":"ε-маңай аралығы. Аралықты жазыңыз: шексіздік - oo, бірігу - U.","q":"$|x^2-9|< 7$ теңсіздігін қанағаттандыратын оң $x$ мәндерінің жиынын жазыңыз.","a":"(sqrt(2); 4)"},{"id":"m4-1-tf2:0","l":1,"lvl":"hard","type":"tf","ctx":"Шектер және амалдар: ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\lim_{x\\to a}f(x)$ бар, ал $\\lim_{x\\to a}g(x)$ жоқ болса, онда $\\lim_{x\\to a}(f+g)$ жоқ.","a":true,"e":"Ақиқат: қосынды шегі бар болса, $g=(f+g)-f$ айырмасының шегі де бар болар еді (шектер арифметикасы), ал ол жоқ."},{"id":"m4-1-tf2:1","l":1,"lvl":"hard","type":"tf","ctx":"Шектер және амалдар: ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\lim f$ және $\\lim g$ екеуі де жоқ болса, онда $\\lim(f\\cdot g)$ да жоқ.","a":false,"e":"Жалған: $f=g=\\mathrm{sgn}(x)$ нөлде шегі жоқ, бірақ $f\\cdot g=1$ ($x\\ne0$), шегі 1."},{"id":"m4-1-tf2:2","l":1,"lvl":"hard","type":"tf","ctx":"Шектер және амалдар: ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\lim_{x\\to a}f(x)=L$ және $L>0$ болса, $a$-ның қандай да бір (тесілген) маңайында $f(x)>0$.","a":true,"e":"Ақиқат: $\\varepsilon=L/2$ алсақ, $f(x)>L-L/2=L/2>0$ шығады."},{"id":"m4-1-tf2:3","l":1,"lvl":"hard","type":"tf","ctx":"Шектер және амалдар: ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\lim_{x\\to a}f(x)=0$ және $g$ шектелген болса, $\\lim_{x\\to a}f(x)g(x)=0$.","a":true,"e":"Ақиқат: $|fg|\\le M|f|\\to0$. Мысал: $x\\sin\\frac1x$."},{"id":"m4-1-conj:0","l":1,"lvl":"hard","type":"num","ctx":"Түбірлі өрнектің шегі. Жауапты бөлшекпен не ондық түрде жазыңыз (мысалы, 1/6).","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\sqrt{x+9}-3}{x}$","a":"1/6"},{"id":"m4-1-conj:1","l":1,"lvl":"hard","type":"num","ctx":"Түбірлі өрнектің шегі. Жауапты бөлшекпен не ондық түрде жазыңыз (мысалы, 1/6).","q":"$\\displaystyle\\lim_{x\\to4}\\dfrac{\\sqrt{x}-2}{x-4}$","a":"1/4"},{"id":"m4-1-param-a:0","l":1,"lvl":"hard","type":"num","ctx":"Шек бар болу үшін параметр. Жауапты санмен жазыңыз.","q":"$f(x)=\\begin{cases}ax-1,&x< 2\\\\ x^2+1,&x\\ge2\\end{cases}$. $\\lim_{x\\to2}f(x)$ болуы үшін $a$ неге тең болуы керек?","a":3},{"id":"m4-1-param-a:1","l":1,"lvl":"hard","type":"num","ctx":"Шек бар болу үшін параметр. Жауапты санмен жазыңыз.","q":"$g(x)=\\begin{cases}x^2+bx,&x< 1\\\\ 3x+2,&x>1\\end{cases}$. $\\lim_{x\\to1}g(x)$ болуы үшін $b$ неге тең?","a":4},{"id":"m4-1-table:0","l":1,"lvl":"hard","type":"matrix","ctx":"Мәндер кестесі арқылы шекті бағалау. Ұяшықтарға сандарды жазыңыз.","q":"$g(x)=\\dfrac{x^2-4}{x-2}$ функциясының $x=1{,}9;\\ 1{,}99;\\ 2{,}01;\\ 2{,}1$ нүктелеріндегі мәндерін жол түрінде жазыңыз.","orient":"row","name":"$g(x)$:","a":[3.9,3.99,4.01,4.1],"tol":0.0001},{"id":"m4-1-inf:0","l":1,"lvl":"hard","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{4x^2+1}{2x^2-x}$","a":2},{"id":"m4-1-inf:1","l":1,"lvl":"hard","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to-\\infty}\\dfrac{3x-1}{x+5}$","a":3},{"id":"m4-1-inf:2","l":1,"lvl":"hard","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{5x}{x^2+1}$","a":0},{"id":"m4-1-multi:0","l":1,"lvl":"hard","type":"choice","ctx":"Шектің жоқтығының себебі. Әр функция үшін $x\\to0$ кезінде шектің жоқтығының дұрыс себебін таңдаңыз.","q":"$f(x)=\\dfrac{|x|}{x}$","o":["Сол және оң жақты шектер әртүрлі","Шексіздікке кетеді","Тербеледі","Мән анықталмаған"],"a":0,"e":"Оң жақта $f=1$, сол жақта $f=-1$."},{"id":"m4-1-multi:1","l":1,"lvl":"hard","type":"choice","ctx":"Шектің жоқтығының себебі. Әр функция үшін $x\\to0$ кезінде шектің жоқтығының дұрыс себебін таңдаңыз.","q":"$g(x)=\\dfrac{1}{x^2}$","o":["Екі жақта да $+\\infty$-ке ұмтылады: шек ақырлы емес","Тербеледі","Сол және оң жақты шектер ақырлы әртүрлі сандар","Мән анықталмаған болғандықтан шек жоқ"],"a":0,"e":"Екі жақты шек $+\\infty$ (ақырлы сан емес). Мән анықталмағандығы шектің жоқтығының себебі емес."},{"id":"m4-1-multi:2","l":1,"lvl":"hard","type":"choice","ctx":"Шектің жоқтығының себебі. Әр функция үшін $x\\to0$ кезінде шектің жоқтығының дұрыс себебін таңдаңыз.","q":"$h(x)=\\sin\\dfrac{1}{x}$","o":["Нөл маңайында $-1$ мен $1$ арасында шексіз тербеледі","Шексіздікке кетеді","Бір жақты шектері әртүрлі ақырлы сандар","Мәні жоқ"],"a":0,"e":"6-қорытудағы екі тізбек шектері $1$ және $-1$ болады."},{"id":"w21-q0","l":1,"lvl":"quiz","type":"choice","q":"lim (x → 3) (x² − 9)/(x − 3) неге тең?","o":["0","3","6","шегі жоқ"],"a":2,"e":"(x² − 9)/(x − 3) = x + 3, x ≠ 3. Шек 3 + 3 = 6. Нүктенің өзінде функция анықталмаған, бірақ шек бар."},{"id":"w21-q1","l":1,"lvl":"quiz","type":"choice","q":"f(x) = |x|/x функциясы үшін x → 0 кезінде не дұрыс?","o":["сол жақты шек −1, оң жақты шек 1, шек жоқ","шек 0","шек 1","шек +∞"],"a":0,"e":"x > 0 үшін f = 1, x < 0 үшін f = −1. Бір жақты шектер әртүрлі, сондықтан екі жақты шек жоқ."},{"id":"w21-q2","l":1,"lvl":"quiz","type":"choice","q":"lim (x → 1) (4x − 1) = 3. ε = 0,2 үшін ең үлкен δ неге тең?","o":["0,2","0,8","0,1","0,05"],"a":3,"e":"|4x − 1 − 3| = 4|x − 1| < 0,2 ⇒ |x − 1| < 0,05, δ = ε/4 = 0,05."},{"id":"w21-q3","l":1,"lvl":"quiz","type":"choice","q":"Шектің анықтамасындағы 0 < |x − a| шарты нені білдіреді?","o":["x = a болуы міндетті","x = a нүктесі қарастырылмайды","f(a) = L","f үзіліссіз"],"a":1,"e":"Шек нүктенің өзіндегі мәнге тәуелді емес, сондықтан x = a алынып тасталады."},{"id":"w21-q4","l":1,"lvl":"quiz","type":"choice","q":"lim (x → +∞) (3x + 1)/(x − 2) неге тең?","o":["1","−2","3","+∞"],"a":2,"e":"Алымы мен бөлгішін x-ке бөлеміз: (3 + 1/x)/(1 − 2/x) → 3/1 = 3. Көлденең асимптота y = 3."},{"id":"w21-q5","l":1,"lvl":"quiz","type":"choice","q":"lim (x → 0) x·sin(1/x) неге тең?","o":["0","1","шегі жоқ","+∞"],"a":0,"e":"|x·sin(1/x)| ≤ |x| → 0. Көбейткіштердің біреуінің шегі жоқ болса да, көбейтіндінің шегі 0."},{"id":"w21-q6","l":1,"lvl":"quiz","type":"choice","q":"f(x) = 1/(x − 5) функциясы үшін x → 5⁺ кезінде не болады?","o":["f → 0","f → −∞","f → 5","f → +∞"],"a":3,"e":"x > 5 болса, x − 5 оң және нөлге ұмтылады, сондықтан 1/(x − 5) → +∞. Ал x → 5⁻ кезінде −∞. Тік асимптота x = 5."},{"id":"w21-q7","l":1,"lvl":"quiz","type":"choice","q":"Шектің жалғыздығын дәлелдегенде ε-ны қалай таңдайды?","o":["ε = |L₁| + |L₂|","ε = |L₁ − L₂|/2","ε = 1","ε = 0"],"a":1,"e":"ε = |L₁ − L₂|/2 болса, f(x) бір мезгілде екі санға ε-нан жақын болуы мүмкін емес: үшбұрыш теңсіздігі қайшылыққа әкеледі."},{"id":"m4-2-subst:0","l":2,"lvl":"easy","type":"num","ctx":"Тікелей қою. Алдымен қоюға болатынын тексеріңіз (бөлгіш нөл емес пе?). Жауапты санмен не бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to2}\\dfrac{x^3-2x}{x+1}$","a":"4/3"},{"id":"m4-2-subst:1","l":2,"lvl":"easy","type":"num","ctx":"Тікелей қою. Алдымен қоюға болатынын тексеріңіз (бөлгіш нөл емес пе?). Жауапты санмен не бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\cos x+2}{e^x+1}$","a":"3/2"},{"id":"m4-2-tf:0","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\lim_{x\\to0}\\dfrac{\\sin x}{x}=1$ тек $x$ градуспен берілгенде дұрыс.","a":false,"e":"Жалған: радианмен дұрыс. Градуспен шек $\\frac{\\pi}{180}$."},{"id":"m4-2-tf:1","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\dfrac00$ әрдайым 1-ге тең.","a":false,"e":"Жалған: $\\frac00$ анықталмағандық, нәтиже өрнекке тәуелді."},{"id":"m4-2-tf:2","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\lim_{x\\to\\infty}\\left(1+\\dfrac1x\\right)^x=e$.","a":true,"e":"Ақиқат: Теорема 2.4."},{"id":"m4-2-tf:3","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\lim_{x\\to\\infty}\\dfrac{2x+1}{x^3}=2$.","a":false,"e":"Жалған: бөлгіштің дәрежесі жоғары, шек 0."},{"id":"m4-2-tf:4","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$g\\le f\\le h$ және $\\lim g=\\lim h=3$ болса, $\\lim f=3$.","a":true,"e":"Ақиқат: қысу теоремасы."},{"id":"m4-2-forms:0","l":2,"lvl":"easy","type":"choice","ctx":"Анықталмағандық түрін тану. Әр шектің түрін анықтаңыз.","q":"$\\displaystyle\\lim_{x\\to2}\\dfrac{x^2-4}{x-2}$ шегі қай түрде?","o":["$\\dfrac00$","$\\dfrac\\infty\\infty$","$1^\\infty$","$\\infty-\\infty$"],"a":0,"e":"$x=2$ қойсақ, алым мен бөлгіш екеуі де 0."},{"id":"m4-2-forms:1","l":2,"lvl":"easy","type":"choice","ctx":"Анықталмағандық түрін тану. Әр шектің түрін анықтаңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(1+\\dfrac2x\\right)^{x}$ шегі қай түрде?","o":["$\\dfrac00$","$1^\\infty$","$\\infty-\\infty$","$0\\cdot\\infty$"],"a":1,"e":"Негіз $\\to1$, дәреже $\\to\\infty$."},{"id":"m4-2-forms:2","l":2,"lvl":"easy","type":"choice","ctx":"Анықталмағандық түрін тану. Әр шектің түрін анықтаңыз.","q":"$\\displaystyle\\lim_{x\\to0^+}\\dfrac{1}{x}$ - анықталмағандық па?","o":["иә, $\\frac00$","иә, $\\frac\\infty\\infty$","жоқ, шек $+\\infty$","жоқ, шек 0"],"a":2,"e":"Бөлгіш 0-ге, алым $1$: $\\frac{c}{0}$ түрі, бұл анықталмағандық емес."},{"id":"m4-2-sin:0","l":2,"lvl":"easy","type":"num","ctx":"Бірінші тамаша шектің қарапайым түрлері. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\sin3x}{x}$","a":3},{"id":"m4-2-sin:1","l":2,"lvl":"easy","type":"num","ctx":"Бірінші тамаша шектің қарапайым түрлері. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\tan2x}{x}$","a":2},{"id":"m4-2-sin:2","l":2,"lvl":"easy","type":"num","ctx":"Бірінші тамаша шектің қарапайым түрлері. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{x}{\\sin(x/4)}$","a":4},{"id":"m4-2-factor:0","l":2,"lvl":"medium","type":"num","ctx":"Көбейткіштерге жіктеу. Жауапты бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to3}\\dfrac{x^2-x-6}{x^2-9}$","a":"5/6"},{"id":"m4-2-factor:1","l":2,"lvl":"medium","type":"num","ctx":"Көбейткіштерге жіктеу. Жауапты бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to1}\\dfrac{x^3-1}{x^2-1}$","a":"3/2"},{"id":"m4-2-simp:0","l":2,"lvl":"medium","type":"expr","ctx":"Қысқартылған өрнекті жазу. Қысқарту нәтижесін $x$ арқылы жазыңыз ($x\\ne$ нүкте деп есептейміз). Эквивалентті жазулар қабылданады.","q":"$\\dfrac{x^3-8}{x-2}$ өрнегін қысқартыңыз ($x\\ne2$).","a":"x^2+2*x+4"},{"id":"m4-2-simp:1","l":2,"lvl":"medium","type":"expr","ctx":"Қысқартылған өрнекті жазу. Қысқарту нәтижесін $x$ арқылы жазыңыз ($x\\ne$ нүкте деп есептейміз). Эквивалентті жазулар қабылданады.","q":"$\\dfrac{x^2-5x+6}{x-2}$ өрнегін қысқартыңыз ($x\\ne2$).","a":"x-3"},{"id":"m4-2-exp:0","l":2,"lvl":"medium","type":"num","ctx":"Екінші тамаша шек. Жауапты $e$-нің дәрежесі түрінде жазыңыз (мысалы, exp(6) не e^6 ).","q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(1+\\dfrac{3}{x}\\right)^{2x}$","a":"exp(6)"},{"id":"m4-2-exp:1","l":2,"lvl":"medium","type":"num","ctx":"Екінші тамаша шек. Жауапты $e$-нің дәрежесі түрінде жазыңыз (мысалы, exp(6) не e^6 ).","q":"$\\displaystyle\\lim_{x\\to0}(1+5x)^{1/x}$","a":"exp(5)"},{"id":"m4-2-equiv:0","l":2,"lvl":"medium","type":"choice","ctx":"Баламалық. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"$x\\to0$ кезінде $3x$ шамасына баламалы шамаларды белгілеңіз.","o":["$\\sin3x$","$\\tan3x$","$e^{3x}-1$","$\\sin x$","$3x^2$"],"a":[0,1,2],"e":"$\\sin u\\sim u$, $\\tan u\\sim u$, $e^u-1\\sim u$ ($u=3x$). $\\sin x\\sim x$ ($3x$-ке емес), $3x^2$ жылдамырақ кішірейеді."},{"id":"m4-2-equiv:1","l":2,"lvl":"medium","type":"choice","ctx":"Баламалық. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\ln(1+4x)}{\\sin2x}$ шегі?","o":["$1$","$2$","$4$","$\\frac12$"],"a":1,"e":"$\\ln(1+4x)\\sim4x$, $\\sin2x\\sim2x$; $\\frac{4x}{2x}=2$."},{"id":"m4-2-table:0","l":2,"lvl":"medium","type":"matrix","ctx":"sin(x)/x мәндерінің кестесі. Калькуляторды радиан режиміне қойып, 6 ондық таңбаға дейін жазыңыз.","q":"$h(x)=\\dfrac{\\sin x}{x}$ функциясының $x=0{,}5;\\ 0{,}1;\\ 0{,}01$ нүктелеріндегі мәндері (жол түрінде).","orient":"row","name":"$h(x)$:","a":["2*sin(1/2)","10*sin(1/10)","100*sin(1/100)"],"tol":2e-05},{"id":"m4-2-inf:0","l":2,"lvl":"hard","type":"num","ctx":"∞ − ∞ түрі. Түйіндес өрнекке көбейтіңіз. Жауапты бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to+\\infty}\\left(\\sqrt{x^2+3x}-x\\right)$","a":"3/2"},{"id":"m4-2-inf:1","l":2,"lvl":"hard","type":"num","ctx":"∞ − ∞ түрі. Түйіндес өрнекке көбейтіңіз. Жауапты бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to+\\infty}\\left(\\sqrt{x^2+1}-\\sqrt{x^2-1}\\right)$","a":0},{"id":"m4-2-trig:0","l":2,"lvl":"hard","type":"num","ctx":"Тригонометриялық шектер. Жауапты санмен не бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{1-\\cos6x}{x^2}$","a":18},{"id":"m4-2-trig:1","l":2,"lvl":"hard","type":"num","ctx":"Тригонометриялық шектер. Жауапты санмен не бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\tan x-\\sin x}{x^3}$","a":"1/2"},{"id":"m4-2-power:0","l":2,"lvl":"hard","type":"num","ctx":"1^∞ түрінің жалпы жағдайы. Жауапты $e$-нің дәрежесі түрінде жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(\\dfrac{x}{x+2}\\right)^x$","a":"exp(-2)"},{"id":"m4-2-power:1","l":2,"lvl":"hard","type":"num","ctx":"1^∞ түрінің жалпы жағдайы. Жауапты $e$-нің дәрежесі түрінде жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}(\\cos x)^{1/x^2}$","a":"exp(-1/2)"},{"id":"m4-2-tf2:0","l":2,"lvl":"hard","type":"tf","ctx":"Баламаларды қолдану шектері. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$x\\to0$ кезінде $\\sin x-x\\sim0$ деп алып, $\\displaystyle\\lim\\dfrac{\\sin x-x}{x^3}=0$ деуге болады.","a":false,"e":"Жалған: қосындыда баламаны ауыстыруға болмайды. Нақты шек $-\\frac16$ (Тейлор қатарынан: $\\sin x=x-\\frac{x^3}{6}+\\dots$)."},{"id":"m4-2-tf2:1","l":2,"lvl":"hard","type":"tf","ctx":"Баламаларды қолдану шектері. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\sin x}{x}$ және $\\displaystyle\\lim_{x\\to0}\\dfrac{\\tan x}{x}$ бірдей мән береді.","a":true,"e":"Ақиқат: екеуі де 1."},{"id":"m4-2-tf2:2","l":2,"lvl":"hard","type":"tf","ctx":"Баламаларды қолдану шектері. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\dfrac{\\sin x}{x}=1$.","a":false,"e":"Жалған: $|\\sin x|\\le1$, сондықтан қысу бойынша шек 0. Бірінші тамаша шек $x\\to0$ үшін ғана."},{"id":"m4-2-tf2:3","l":2,"lvl":"hard","type":"tf","ctx":"Баламаларды қолдану шектері. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f(x)=\\dfrac{x^2}{x}$ функциясы $x=0$ нүктесінде анықталмаған, сондықтан $\\lim_{x\\to0}f(x)$ жоқ.","a":false,"e":"Жалған: $x\\ne0$ үшін $f(x)=x$, сондықтан шек бар және 0-ге тең; нүктеде анықталмағандық шектің жоқтығын білдірмейді."},{"id":"m4-2-find-a:0","l":2,"lvl":"hard","type":"num","ctx":"Параметрді табу. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(1+\\dfrac{a}{x}\\right)^{3x}=e^6$ болса, $a$ неге тең?","a":2},{"id":"m4-2-find-a:1","l":2,"lvl":"hard","type":"num","ctx":"Параметрді табу. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\sin(ax)}{\\ln(1+4x)}=\\dfrac32$ болса, $a$ неге тең?","a":6},{"id":"w22-q0","l":2,"lvl":"quiz","type":"choice","q":"lim (x → 0) sin(7x)/x неге тең?","o":["1","7","1/7","0"],"a":1,"e":"sin(7x)/x = 7·sin(7x)/(7x) → 7·1 = 7."},{"id":"w22-q1","l":2,"lvl":"quiz","type":"choice","q":"lim (x → ∞) (1 + 1/x)^(2x) неге тең?","o":["1","e","e²","∞"],"a":2,"e":"(1 + 1/x)^(2x) = [(1 + 1/x)^x]² → e²."},{"id":"w22-q2","l":2,"lvl":"quiz","type":"choice","q":"lim (x → ∞) (5x² + 3)/(2x² − x) неге тең?","o":["5/2","0","∞","3/(−1)"],"a":0,"e":"Дәрежелері тең (2 = 2), шек жетекші коэффициенттердің қатынасы 5/2."},{"id":"w22-q3","l":2,"lvl":"quiz","type":"choice","q":"lim (x → 0) (1 − cos x)/x² неге тең?","o":["0","1","2","1/2"],"a":3,"e":"1 − cos x = 2sin²(x/2), сондықтан өрнек (1/2)·(sin(x/2)/(x/2))² → 1/2."},{"id":"w22-q4","l":2,"lvl":"quiz","type":"choice","q":"Қайсысы анықталмағандық емес?","o":["0/0","1/0 (алым 1, бөлгіш 0-ге ұмтылады)","∞ − ∞","1^∞"],"a":1,"e":"c/0 (c ≠ 0) түрі шексіздікке апарады, оның шегі белгілі (±∞ не жоқ). Қалғандары анықталмағандықтар."},{"id":"w22-q5","l":2,"lvl":"quiz","type":"choice","q":"lim (x → 2) (x² − 4)/(x − 2) неге тең?","o":["0","2","4","жоқ"],"a":2,"e":"(x − 2)(x + 2)/(x − 2) = x + 2 (x ≠ 2), шек 2 + 2 = 4."},{"id":"w22-q6","l":2,"lvl":"quiz","type":"choice","q":"x → 0 кезінде қайсысы 3x шамасына баламалы емес?","o":["3x²","sin 3x","tan 3x","e^(3x) − 1"],"a":0,"e":"3x²/(3x) = x → 0, 1-ге ұмтылмайды. Қалған үшеуі 3x-ке баламалы (u = 3x → 0)."},{"id":"w22-q7","l":2,"lvl":"quiz","type":"choice","q":"lim (x → +∞) (√(x² + 3x) − x) неге тең?","o":["0","3","∞","3/2"],"a":3,"e":"Түйіндеспен көбейтеміз: 3x/(√(x² + 3x) + x) = 3/(√(1 + 3/x) + 1) → 3/2."},{"id":"m4-3-tf:0","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Көпмүшелік бүкіл нақты түзуде үзіліссіз.","a":true,"e":"Ақиқат: тұрақты мен $x$-тің үзіліссіздігінен, қосынды мен көбейтіндінің үзіліссіздігінен шығады."},{"id":"m4-3-tf:1","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f(a)$ анықталған болса, $f$ функциясы $a$ нүктесінде үзіліссіз.","a":false,"e":"Жалған: шек те бар және мәнге тең болуы керек."},{"id":"m4-3-tf:2","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\dfrac{|x|}{x}$ функциясының нөлде жойылатын үзілісі бар.","a":false,"e":"Жалған: бір жақты шектер $-1$ және $1$, олар әртүрлі: бұл секіру."},{"id":"m4-3-tf:3","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Үзіліссіз функция $[a;b]$ кесіндісінде ең үлкен мәніне жетеді.","a":true,"e":"Ақиқат: Вейерштрасс теоремасы."},{"id":"m4-3-tf:4","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f(-1)=-1$, $f(1)=1$, $f(x)=\\frac1x$ ($x\\ne0$) болғандықтан $f$-тің $(-1;1)$ аралығында нөлі бар.","a":false,"e":"Жалған: $f$ нөлде үзіліске ие, теорема кесіндідегі үзіліссіздікті талап етеді. $\\frac1x$ ешқашан 0 болмайды."},{"id":"m4-3-types:0","l":3,"lvl":"easy","type":"choice","ctx":"Үзіліс түрін тану. Дұрыс жауапты таңдаңыз.","q":"$f(x)=\\dfrac{\\sin x}{x}$ функциясының $x=0$ нүктесіндегі үзілісі қандай?","o":["жойылатын","секіру","екінші текті","үзіліс жоқ, $f(0)=1$ берілген"],"a":0,"e":"Шек 1, ал $f(0)$ анықталмаған: бір жақты шектер тең, жойылатын үзіліс."},{"id":"m4-3-types:1","l":3,"lvl":"easy","type":"choice","ctx":"Үзіліс түрін тану. Дұрыс жауапты таңдаңыз.","q":"$f(x)=\\dfrac{1}{x-3}$ функциясының $x=3$ нүктесіндегі үзілісі қандай?","o":["жойылатын","секіру","екінші текті","үзіліс жоқ"],"a":2,"e":"Бір жақты шектер $\\pm\\infty$: екінші текті, тік асимптота."},{"id":"m4-3-types:2","l":3,"lvl":"easy","type":"choice","ctx":"Үзіліс түрін тану. Дұрыс жауапты таңдаңыз.","q":"$f(x)=\\begin{cases}x,&x< 1\\\\ x+2,&x\\ge1\\end{cases}$ функциясы $x=1$ нүктесінде?","o":["үзіліссіз","жойылатын үзіліс","секіру 2-ге тең","екінші текті"],"a":2,"e":"Сол жақ шек 1, оң жақ шек 3. Секіру $3-1=2$."},{"id":"m4-3-limit:0","l":3,"lvl":"easy","type":"num","ctx":"Үзіліссіз функцияның шегі. Үзіліссіздікті пайдаланып шекті есептеңіз. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to2}\\sqrt{x^2+5}$","a":3},{"id":"m4-3-limit:1","l":3,"lvl":"easy","type":"num","ctx":"Үзіліссіз функцияның шегі. Үзіліссіздікті пайдаланып шекті есептеңіз. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\dfrac{\\cos x+1}{e^x+3}$","a":"1/2"},{"id":"m4-3-limit:2","l":3,"lvl":"easy","type":"num","ctx":"Үзіліссіз функцияның шегі. Үзіліссіздікті пайдаланып шекті есептеңіз. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\pi/2}\\sin(3x)$","a":-1},{"id":"m4-3-param1:0","l":3,"lvl":"medium","type":"num","ctx":"Үзіліссіздік шарты бойынша параметр. Жауапты санмен жазыңыз.","q":"$f(x)=\\begin{cases}\\dfrac{x^2-9}{x-3},&x\\ne3\\\\ a,&x=3\\end{cases}$ функциясы $x=3$ нүктесінде үзіліссіз болу үшін $a$ неге тең?","a":6},{"id":"m4-3-param1:1","l":3,"lvl":"medium","type":"num","ctx":"Үзіліссіздік шарты бойынша параметр. Жауапты санмен жазыңыз.","q":"$g(x)=\\begin{cases}\\dfrac{\\sin 5x}{x},&x\\ne0\\\\ b,&x=0\\end{cases}$ үзіліссіз болу үшін $b$ неге тең?","a":5},{"id":"m4-3-two-sided:0","l":3,"lvl":"medium","type":"num","ctx":"Бөлікті функцияның бөліну нүктесі. $f(x)=\\begin{cases}x^2+k,&x<1\\\\ 4x-1,&x\\ge1\\end{cases}$ функциясы берілген.","q":"$x=1$ нүктесінде сол жақты шек $k$ арқылы қалай жазылады? $k=0$ болғанда оның мәнін көрсетіңіз.","a":1},{"id":"m4-3-two-sided:1","l":3,"lvl":"medium","type":"num","ctx":"Бөлікті функцияның бөліну нүктесі. $f(x)=\\begin{cases}x^2+k,&x<1\\\\ 4x-1,&x\\ge1\\end{cases}$ функциясы берілген.","q":"$f$ функциясы $x=1$ нүктесінде үзіліссіз болу үшін $k$ неге тең?","a":2},{"id":"m4-3-cont-set:0","l":3,"lvl":"medium","type":"interval","ctx":"Үзіліссіздік аралықтары. Функция үзіліссіз болатын жиынды аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$f(x)=\\dfrac{x+1}{x^2-4}$ функциясы қай жерде үзіліссіз?","a":"(-oo; -2) U (-2; 2) U (2; oo)"},{"id":"m4-3-cont-set:1","l":3,"lvl":"medium","type":"interval","ctx":"Үзіліссіздік аралықтары. Функция үзіліссіз болатын жиынды аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$g(x)=\\ln(x^2-1)$ функциясы қай жерде үзіліссіз?","a":"(-oo; -1) U (1; oo)"},{"id":"m4-3-fix:0","l":3,"lvl":"medium","type":"expr","ctx":"Жойылатын үзілісті жөндеу. Үзілісті жоятын жаңа функцияның формуласын $x$ арқылы жазыңыз (барлық нүктеде жарамды формула).","q":"$f(x)=\\dfrac{x^2-5x+6}{x-2}$, $x\\ne2$. $x=2$ нүктесіндегі үзілісті жоятын өрнек (барлық $x$ үшін).","a":"x-3"},{"id":"m4-3-ivt:0","l":3,"lvl":"medium","type":"choice","ctx":"Аралық мән теоремасы. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"Қай теңдеулердің түбірі $(0;1)$ аралығында бар екені аралық мән теоремасынан бірден шығады?","o":["$x^3+x-1=0$","$x^2+1=0$","$\\cos x-x=0$","$x^2-2=0$"],"a":[0,2],"e":"$f(0)=-1<0$, $f(1)=1>0$ ($x^3+x-1$); $\\cos0-0=1>0$, $\\cos1-1<0$. $x^2+1$ оң; $x^2-2$ екі ұшта да теріс."},{"id":"m4-3-ivt:1","l":3,"lvl":"medium","type":"choice","ctx":"Аралық мән теоремасы. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"Қай жағдайда теорема қолданылмайды?","o":["функция кесіндіде үзіліссіз емес","$f(a)f(b)< 0$","$f$ көпмүшелік","$f$ монотонды"],"a":0,"e":"Теорема үзіліссіздікті талап етеді. Қалған жағдайлар қолдануға кедергі емес."},{"id":"m4-3-bisect:0","l":3,"lvl":"medium","type":"matrix","ctx":"Екіге бөлудің алғашқы қадамдары. $f(x)=x^3+x-1$ функциясы үшін $[0;1]$ кесіндісінде екіге бөлу әдісін қолданыңыз. Мәндерді ондық бөлшекпен жазыңыз.","q":"$f(0{,}5)$ және $f(0{,}75)$ мәндерін жол түрінде жазыңыз.","orient":"row","name":"$f$:","a":[-0.375,0.171875],"tol":0.0001},{"id":"m4-3-count:0","l":3,"lvl":"hard","type":"num","ctx":"Екіге бөлу қадамдарының саны. Формула 3.2 бойынша қадам санын табыңыз. Жауапты бүтін санмен жазыңыз.","q":"$[0;1]$ кесіндісінде түбірді $10^{-3}$ қателікпен табу үшін қанша қадам керек ($|x^*-c_n|\\le\\frac{1}{2^{n+1}}\\le10^{-3}$ шартын қанағаттандыратын ең кіші бүтін $n$)?","a":9},{"id":"m4-3-count:1","l":3,"lvl":"hard","type":"num","ctx":"Екіге бөлу қадамдарының саны. Формула 3.2 бойынша қадам санын табыңыз. Жауапты бүтін санмен жазыңыз.","q":"$[1;3]$ кесіндісінде, қателік $0{,}01$-ден кем болуы үшін қажетті ең кіші $n$ ($\\frac{2}{2^{n+1}}\\le0{,}01$).","a":7},{"id":"m4-3-two-par:0","l":3,"lvl":"hard","type":"num","ctx":"Екі параметрді табу. Жауапты санмен жазыңыз.","q":"$f(x)=\\begin{cases}x+1,&x< 0\\\\ ax+b,&0\\le x\\le1\\\\ 3x-2,&x>1\\end{cases}$ функциясы бүкіл түзуде үзіліссіз болу үшін $a+b$ мәнін табыңыз (жауабы сан).","a":1},{"id":"m4-3-tf2:0","l":3,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ үзіліссіз, $g$ үзілісті болса, $f+g$ үзілісті.","a":true,"e":"Ақиқат: $f+g$ үзіліссіз болса, $g=(f+g)-f$ да үзіліссіз болар еді."},{"id":"m4-3-tf2:1","l":3,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ және $g$ үзілісті болса, $f+g$ да міндетті түрде үзілісті.","a":false,"e":"Жалған: $f=\\frac{|x|}{x}$, $g=-\\frac{|x|}{x}$ нөлде үзілісті, бірақ қосындысы $0$ тұрақты."},{"id":"m4-3-tf2:2","l":3,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$|f|$ үзіліссіз болса, $f$ да үзіліссіз.","a":false,"e":"Жалған: $f=\\begin{cases}1,&x\\ge0\\\\ -1,&x< 0\\end{cases}$ үзілісті, ал $|f|=1$ үзіліссіз."},{"id":"m4-3-tf2:3","l":3,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ үзіліссіз болса, $|f|$ да үзіліссіз.","a":true,"e":"Ақиқат: $|f|=\\sqrt{f^2}$ немесе $||u|-|v||\\le|u-v|$."},{"id":"m4-3-root:0","l":3,"lvl":"hard","type":"num","ctx":"Түбірдің бар болуы: таңбаларды салыстыру. Жауапты санмен жазыңыз.","q":"$f(x)=x^3-3x+1$ көпмүшелігі $[-2;2]$ кесіндісінде үзіліссіз. $f(-2)\\cdot f(2)$ көбейтіндісі неге тең?","a":-3},{"id":"m4-3-root:1","l":3,"lvl":"hard","type":"num","ctx":"Түбірдің бар болуы: таңбаларды салыстыру. Жауапты санмен жазыңыз.","q":"Сол көпмүшеліктің $[-2;2]$ ішінде кем дегенде қанша түбірі бар екені $f(-2),f(-1),f(0),f(1),f(2)$ таңбаларынан шығады? ($f(-1)=3,\\ f(0)=1,\\ f(1)=-1$.)","a":3},{"id":"m4-3-range:0","l":3,"lvl":"hard","type":"interval","ctx":"Үзіліссіз функцияның кесіндідегі мәндер жиыны. Мәндер жиынын аралық түрінде жазыңыз.","q":"$f(x)=x^2-4x+1$ функциясының $[0;3]$ кесіндісіндегі мәндер жиыны.","a":"[-3; 1]"},{"id":"m4-3-range:1","l":3,"lvl":"hard","type":"interval","ctx":"Үзіліссіз функцияның кесіндідегі мәндер жиыны. Мәндер жиынын аралық түрінде жазыңыз.","q":"$g(x)=\\sin x$ функциясының $[0;\\pi]$ кесіндісіндегі мәндер жиыны.","a":"[0; 1]"},{"id":"w23-q0","l":3,"lvl":"quiz","type":"choice","q":"f(x) = (x² − 1)/(x − 1) (x ≠ 1), f(1) = a. a қандай болғанда f функциясы x = 1 нүктесінде үзіліссіз болады?","o":["0","1","2","4"],"a":2,"e":"x ≠ 1 үшін f(x) = x + 1, шек 1 + 1 = 2. Үзіліссіздікте f(1) = шек = 2."},{"id":"w23-q1","l":3,"lvl":"quiz","type":"choice","q":"f(x) = |x|/x функциясының x = 0 нүктесіндегі үзілісі қандай?","o":["секіру (бірінші текті)","жойылатын","екінші текті","үзіліс жоқ"],"a":0,"e":"Сол жақ шек −1, оң жақ шек 1: ақырлы, бірақ әртүрлі, демек секіру."},{"id":"w23-q2","l":3,"lvl":"quiz","type":"choice","q":"f(x) = 1/(x − 2) функциясының x = 2 нүктесіндегі үзілісі қандай?","o":["жойылатын","секіру","үзіліс жоқ","екінші текті (тік асимптота)"],"a":3,"e":"x → 2⁺ кезінде +∞, x → 2⁻ кезінде −∞: бір жақты шектер шексіз."},{"id":"w23-q3","l":3,"lvl":"quiz","type":"choice","q":"x³ + x − 1 = 0 теңдеуінің түбірі қай аралықта бар екені аралық мән теоремасынан шығады?","o":["(−1; 0)","(0; 1)","(1; 2)","(2; 3)"],"a":1,"e":"f(0) = −1 < 0, f(1) = 1 > 0, f үзіліссіз (көпмүшелік), сондықтан (0; 1) ішінде нөл бар."},{"id":"w23-q4","l":3,"lvl":"quiz","type":"choice","q":"Екіге бөлу әдісінде [0; 1] кесіндісінде n = 4 қадамнан кейін ортаның қателігі ең көбі қанша?","o":["1/8","1/16","1/32","1/4"],"a":2,"e":"|x* − c_n| ≤ (b − a)/2^(n+1) = 1/2⁵ = 1/32."},{"id":"w23-q5","l":3,"lvl":"quiz","type":"choice","q":"Қай функция x = 0 нүктесінде (f(0) = 0 деп) үзіліссіз?","o":["x·sin(1/x)","sin(1/x)","1/x","|x|/x"],"a":0,"e":"|x·sin(1/x)| ≤ |x| → 0 = f(0). Қалғандарында нөлде шек жоқ не шексіз."},{"id":"w23-q6","l":3,"lvl":"quiz","type":"choice","q":"Вейерштрасс теоремасы қай жағдайда дұрыс?","o":["f(x) = 1/x, (0; 1]","f(x) = x, (0; 1)","f(x) = tan x, [0; π]","f(x) = x², [−1; 2]"],"a":3,"e":"Теорема кесіндіде үзіліссіз функцияға қатысты. Қалған үш жағдайда не аралық ашық, не функция үзілісті."},{"id":"w23-q7","l":3,"lvl":"quiz","type":"choice","q":"f(x) = ln(x² − 4) функциясы қай жерде үзіліссіз?","o":["x > 2","x < −2 және x > 2","−2 < x < 2","барлық x"],"a":1,"e":"Логарифм аргументі оң болуы керек: x² − 4 > 0 ⇒ |x| > 2. Облыстың барлық нүктесінде функция үзіліссіз."},{"id":"m4-4-slope:0","l":4,"lvl":"easy","type":"num","ctx":"Қиюшының еңісі. Жауапты санмен жазыңыз.","q":"$f(x)=x^2$ графигінің $A(1;1)$ және $B(3;9)$ нүктелері арқылы өтетін қиюшысының еңісі.","a":4},{"id":"m4-4-slope:1","l":4,"lvl":"easy","type":"num","ctx":"Қиюшының еңісі. Жауапты санмен жазыңыз.","q":"Сол функцияның $[1;1{,}1]$ аралығындағы орташа өзгеру жылдамдығы.","a":2.1},{"id":"m4-4-tf:0","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Нүктеде дифференциалданатын функция сол нүктеде үзіліссіз.","a":true,"e":"Ақиқат: Теорема 4.1."},{"id":"m4-4-tf:1","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Нүктеде үзіліссіз функция сол нүктеде міндетті түрде дифференциалданады.","a":false,"e":"Жалған: $|x|$ нөлде үзіліссіз, бірақ туындысы жоқ."},{"id":"m4-4-tf:2","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(x^3)'=3x^2$.","a":true,"e":"Ақиқат: $(x^n)'=nx^{n-1}$, $n=3$."},{"id":"m4-4-tf:3","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Тұрақты функцияның туындысы 1-ге тең.","a":false,"e":"Жалған: тұрақты функцияның графигі көлденең түзу, еңісі 0."},{"id":"m4-4-tf:4","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\sin x)'=-\\cos x$.","a":false,"e":"Жалған: $(\\sin x)'=\\cos x$, ал $(\\cos x)'=-\\sin x$."},{"id":"m4-4-deriv:0","l":4,"lvl":"easy","type":"num","ctx":"Нүктедегі туынды мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=x^3$ үшін $f'(2)$.","a":12},{"id":"m4-4-deriv:1","l":4,"lvl":"easy","type":"num","ctx":"Нүктедегі туынды мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=\\dfrac1x$ үшін $f'(2)$.","a":"-1/4"},{"id":"m4-4-deriv:2","l":4,"lvl":"easy","type":"num","ctx":"Нүктедегі туынды мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=\\sqrt x$ үшін $f'(9)$.","a":"1/6"},{"id":"m4-4-tangent:0","l":4,"lvl":"medium","type":"expr","ctx":"Жанаманың теңдеуі. Жанаманы $y=\\dots$ түрінде жазыңыз (эквивалентті теңдеулер қабылданады).","q":"$f(x)=x^2$ параболасына $x=3$ нүктесіндегі жанама.","eq":true,"a":"y=6*x-9"},{"id":"m4-4-tangent:1","l":4,"lvl":"medium","type":"expr","ctx":"Жанаманың теңдеуі. Жанаманы $y=\\dots$ түрінде жазыңыз (эквивалентті теңдеулер қабылданады).","q":"$f(x)=\\dfrac1x$ графигіне $x=2$ нүктесіндегі жанама.","eq":true,"a":"y=-x/4+1"},{"id":"m4-4-velocity:0","l":4,"lvl":"medium","type":"num","ctx":"Лездік жылдамдық. Жауапты санмен жазыңыз.","q":"$s(t)=3t^2+4t$ (метр). $t=3$ с кезіндегі жылдамдық (м/с).","a":22},{"id":"m4-4-velocity:1","l":4,"lvl":"medium","type":"num","ctx":"Лездік жылдамдық. Жауапты санмен жазыңыз.","q":"Сол дененің $t=1$ мен $t=1{,}01$ арасындағы орташа жылдамдығы (м/с).","a":10.03},{"id":"m4-4-diffable:0","l":4,"lvl":"medium","type":"choice","ctx":"Дифференциалдану. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"Қай функциялардың $x=0$ нүктесінде туындысы бар?","o":["$|x|$","$x^2$","$x|x|$","$\\sqrt[3]{x}$","$\\sin x$"],"a":[1,2,4],"e":"$x^2$, $x|x|$ ($f'(0)=0$) және $\\sin x$ ($f'(0)=1$) дифференциалданады. $|x|$ - бұрыш, $\\sqrt[3]{x}$ - тік жанама."},{"id":"m4-4-diffable:1","l":4,"lvl":"medium","type":"choice","ctx":"Дифференциалдану. Дұрыс жауапты таңдаңыз. Бірінші сұрақта бірнеше жауап дұрыс.","q":"$f(x)=|x-2|$ функциясы $x=2$ нүктесінде?","o":["дифференциалданады, $f'(2)=0$","дифференциалданбайды, бірақ үзіліссіз","үзілісті","дифференциалданады, $f'(2)=1$"],"a":1,"e":"Бұрыш: $f'_+(2)=1$, $f'_-(2)=-1$. Үзіліссіз."},{"id":"m4-4-normal:0","l":4,"lvl":"medium","type":"num","ctx":"Нормаль еңісі. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=x^2$ графигіне $x=2$ нүктесінде жүргізілген нормальдің еңісі.","a":"-1/4"},{"id":"m4-4-normal:1","l":4,"lvl":"medium","type":"num","ctx":"Нормаль еңісі. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=\\sqrt x$ графигіне $x=1$ нүктесінде жүргізілген нормальдің еңісі.","a":-2},{"id":"m4-4-linear:0","l":4,"lvl":"medium","type":"expr","ctx":"Сызықтық жуықтау. Жуықтау функциясын $x$ арқылы жазыңыз.","q":"$f(x)=\\sqrt x$ үшін $a=4$ нүктесіндегі сызықтық жуықтау $L(x)=f(a)+f'(a)(x-a)$.","a":"2+(x-4)/4"},{"id":"m4-4-linear:1","l":4,"lvl":"medium","type":"expr","ctx":"Сызықтық жуықтау. Жуықтау функциясын $x$ арқылы жазыңыз.","q":"$f(x)=e^x$ үшін $a=0$ нүктесіндегі сызықтық жуықтау.","a":"1+x"},{"id":"m4-4-table:0","l":4,"lvl":"medium","type":"matrix","ctx":"Айырымдық қатынастар кестесі. $f(x)=x^2$, $a=1$ үшін $\\dfrac{f(1+h)-f(1)}{h}$ мәнін $h=1;\\ 0{,}5;\\ 0{,}1;\\ 0{,}01$ нүктелерінде жол түрінде жазыңыз.","q":"Мәндер қатары ($h$ нөлге жақындағанда не байқалады?).","orient":"row","name":"$\\dfrac{\\Delta f}{h}$:","a":[3,2.5,2.1,2.01],"tol":0.0001},{"id":"m4-4-def:0","l":4,"lvl":"hard","type":"num","ctx":"Анықтамадан шек. Туындыны анықтамадағы шек ретінде есептеп, жауапты жазыңыз.","q":"$\\displaystyle\\lim_{h\\to0}\\dfrac{(3+h)^3-27}{h}$","a":27},{"id":"m4-4-def:1","l":4,"lvl":"hard","type":"num","ctx":"Анықтамадан шек. Туындыны анықтамадағы шек ретінде есептеп, жауапты жазыңыз.","q":"$\\displaystyle\\lim_{h\\to0}\\dfrac{\\sin\\left(\\frac\\pi3+h\\right)-\\frac{\\sqrt3}{2}}{h}$","a":"1/2"},{"id":"m4-4-def:2","l":4,"lvl":"hard","type":"num","ctx":"Анықтамадан шек. Туындыны анықтамадағы шек ретінде есептеп, жауапты жазыңыз.","q":"$\\displaystyle\\lim_{x\\to1}\\dfrac{\\ln x}{x-1}$","a":1},{"id":"m4-4-tf2:0","l":4,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f(x)=x|x|$ функциясы нөлде дифференциалданады және $f'(0)=0$.","a":true,"e":"Ақиқат: $\\dfrac{h|h|}{h}=|h|\\to0$."},{"id":"m4-4-tf2:1","l":4,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f(x)=x\\sin\\frac1x$ ($x\\ne0$), $f(0)=0$ функциясы нөлде дифференциалданады.","a":false,"e":"Жалған: $\\dfrac{f(h)-f(0)}{h}=\\sin\\frac1h$, шегі жоқ (21-сабақ, 6-қорыту). Үзіліссіз, бірақ туындысы жоқ."},{"id":"m4-4-tf2:2","l":4,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f(x)=x^2\\sin\\frac1x$ ($x\\ne0$), $f(0)=0$ функциясы нөлде дифференциалданады және $f'(0)=0$.","a":true,"e":"Ақиқат: $\\dfrac{h^2\\sin(1/h)}{h}=h\\sin\\frac1h\\to0$ (қысу)."},{"id":"m4-4-tf2:3","l":4,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ нүктеде дифференциалданса, $|f|$ да дифференциалданады.","a":false,"e":"Жалған: $f(x)=x$ нөлде дифференциалданады, ал $|x|$ жоқ."},{"id":"m4-4-tan-line:0","l":4,"lvl":"hard","type":"expr","ctx":"Параболаға жанама сызу. Теңдеуді $y=\\dots$ түрінде жазыңыз.","q":"$y=x^2-4x+5$ параболасының $x$ осіне параллель жанамасының теңдеуі.","eq":true,"a":"y=1"},{"id":"m4-4-tan-line:1","l":4,"lvl":"hard","type":"expr","ctx":"Параболаға жанама сызу. Теңдеуді $y=\\dots$ түрінде жазыңыз.","q":"$y=x^2$ параболасына $A(1;-3)$ нүктесінен жүргізілген екі жанаманың жанасу нүктесінің абсциссасы оң болатынының теңдеуі.","eq":true,"a":"y=6*x-9"},{"id":"m4-4-incr:0","l":4,"lvl":"hard","type":"interval","ctx":"Өсу аралығы. Туындының таңбасы арқылы функцияның өсетін аралығын жазыңыз (шексіздік - oo).","q":"$f(x)=x^2-6x+1$ функциясы қай аралықта өседі ($f'(x)>0$)?","a":"(3; oo)"},{"id":"m4-4-incr:1","l":4,"lvl":"hard","type":"interval","ctx":"Өсу аралығы. Туындының таңбасы арқылы функцияның өсетін аралығын жазыңыз (шексіздік - oo).","q":"$g(x)=-x^2+4x$ функциясы қай аралықта өседі?","a":"(-oo; 2)"},{"id":"m4-4-approx:0","l":4,"lvl":"hard","type":"num","ctx":"Дифференциалмен жуықтау. Жауапты ондық бөлшекпен жазыңыз.","q":"$\\sqrt{9{,}06}$ шамасын $f(x)=\\sqrt x$, $a=9$ үшін сызықтық жуықтаумен табыңыз.","a":3.01},{"id":"m4-4-approx:1","l":4,"lvl":"hard","type":"num","ctx":"Дифференциалмен жуықтау. Жауапты ондық бөлшекпен жазыңыз.","q":"$\\dfrac{1}{1{,}02}$ шамасын $f(x)=\\frac1x$, $a=1$ үшін жуықтаңыз.","a":0.98},{"id":"w24-q0","l":4,"lvl":"quiz","type":"choice","q":"f(x) = x² − 3x функциясының x = 2 нүктесіндегі туындысы неге тең?","o":["0","1","−2","4"],"a":1,"e":"f'(x) = 2x − 3, f'(2) = 4 − 3 = 1."},{"id":"w24-q1","l":4,"lvl":"quiz","type":"choice","q":"y = √x графигіне x = 4 нүктесіндегі жанаманың теңдеуі қандай?","o":["y = 4x − 14","y = x/2","y = x/4 − 1","y = x/4 + 1"],"a":3,"e":"f(4) = 2, f'(4) = 1/4. y − 2 = (x − 4)/4, яғни y = x/4 + 1."},{"id":"w24-q2","l":4,"lvl":"quiz","type":"choice","q":"s(t) = 5t² + 2t болса, t = 2 кезіндегі лездік жылдамдық қанша?","o":["22","24","12","10"],"a":0,"e":"v(t) = s'(t) = 10t + 2, v(2) = 22."},{"id":"w24-q3","l":4,"lvl":"quiz","type":"choice","q":"f(x) = |x| функциясы x = 0 нүктесінде қандай?","o":["дифференциалданады, f'(0) = 0","үзіліссіз емес","үзіліссіз, бірақ дифференциалданбайды","дифференциалданады, f'(0) = 1"],"a":2,"e":"Бір жақты туындылар 1 және −1: бұрыш. Үзіліссіздік сақталады."},{"id":"w24-q4","l":4,"lvl":"quiz","type":"choice","q":"(ln x)' неге тең (x > 0)?","o":["ln x","1/x","x","e^x"],"a":1,"e":"(ln x)' = lim (1/h)·ln(1 + h/x) = 1/x (екінші тамаша шектің салдары)."},{"id":"w24-q5","l":4,"lvl":"quiz","type":"choice","q":"y = x² графигіне x = 2 нүктесінде жүргізілген нормальдің еңісі қанша?","o":["4","−4","1/4","−1/4"],"a":3,"e":"Жанаманың еңісі f'(2) = 4, нормаль перпендикуляр: −1/4."},{"id":"w24-q6","l":4,"lvl":"quiz","type":"choice","q":"√4,04 шамасын сызықтық жуықтаумен бағалаңыз.","o":["2,01","2,04","2,1","2,001"],"a":0,"e":"f(4) = 2, f'(4) = 1/4: √4,04 ≈ 2 + 0,04/4 = 2,01."},{"id":"w24-q7","l":4,"lvl":"quiz","type":"choice","q":"Қай пікір дұрыс?","o":["Үзіліссіз функция әрдайым дифференциалданады","Үзілісті функцияның туындысы бар болуы мүмкін","Дифференциалданатын функция үзіліссіз","Тұрақты функцияның туындысы 1"],"a":2,"e":"Дифференциалдану үзіліссіздікті туғызады (Теорема 4.1). Керісінше дұрыс емес (|x|), ал тұрақтының туындысы 0."},{"id":"m4-5-values:0","l":5,"lvl":"easy","type":"num","ctx":"Көпмүшелік туындысының мәні. Жауапты санмен жазыңыз.","q":"$f(x)=3x^4-2x^2+x$ үшін $f'(1)$.","a":9},{"id":"m4-5-values:1","l":5,"lvl":"easy","type":"num","ctx":"Көпмүшелік туындысының мәні. Жауапты санмен жазыңыз.","q":"$g(x)=5x^3-7x+2$ үшін $g'(-1)$.","a":8},{"id":"m4-5-tf:0","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(fg)'=f'g'$.","a":false,"e":"Жалған: $(fg)'=f'g+fg'$."},{"id":"m4-5-tf:1","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(f+g)'=f'+g'$.","a":true,"e":"Ақиқат: қосындының туындысы туындылар қосындысы."},{"id":"m4-5-tf:2","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\tan x)'=\\dfrac{1}{\\cos^2x}$.","a":true,"e":"Ақиқат: 4-қорыту."},{"id":"m4-5-tf:3","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\left(\\dfrac{x}{x+1}\\right)'=\\dfrac{1}{1}$.","a":false,"e":"Жалған: $\\dfrac{1\\cdot(x+1)-x\\cdot1}{(x+1)^2}=\\dfrac{1}{(x+1)^2}$."},{"id":"m4-5-tf:4","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\pi^3)'=3\\pi^2$.","a":false,"e":"Жалған: $\\pi^3$ - тұрақты сан, туындысы 0."},{"id":"m4-5-poly:0","l":5,"lvl":"easy","type":"expr","ctx":"Көпмүшелік пен қарапайым өрнектер. Туындыны $x$ арқылы жазыңыз.","q":"$y=x^3-4x^2+5x-7$, $y'=\\ ?$","a":"3*x^2-8*x+5"},{"id":"m4-5-poly:1","l":5,"lvl":"easy","type":"expr","ctx":"Көпмүшелік пен қарапайым өрнектер. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{2}{x}+3\\sqrt x$, $y'=\\ ?$","a":"-2/x^2+3/(2*sqrt(x))","dom":[0.3,5]},{"id":"m4-5-prod:0","l":5,"lvl":"medium","type":"expr","ctx":"Көбейтіндінің туындысы. Туындыны $x$ арқылы жазыңыз (ықшамдау міндетті емес).","q":"$y=x^2e^x$, $y'=\\ ?$","a":"exp(x)*(x^2+2*x)"},{"id":"m4-5-prod:1","l":5,"lvl":"medium","type":"expr","ctx":"Көбейтіндінің туындысы. Туындыны $x$ арқылы жазыңыз (ықшамдау міндетті емес).","q":"$y=(2x-1)\\sin x$, $y'=\\ ?$","a":"2*sin(x)+(2*x-1)*cos(x)"},{"id":"m4-5-prod:2","l":5,"lvl":"medium","type":"expr","ctx":"Көбейтіндінің туындысы. Туындыны $x$ арқылы жазыңыз (ықшамдау міндетті емес).","q":"$y=\\sqrt x\\,\\ln x$, $y'=\\ ?$","a":"ln(x)/(2*sqrt(x))+1/sqrt(x)","dom":[0.3,5]},{"id":"m4-5-quot:0","l":5,"lvl":"medium","type":"expr","ctx":"Бөліндінің туындысы. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{x}{x^2+1}$, $y'=\\ ?$","a":"(1-x^2)/(x^2+1)^2"},{"id":"m4-5-quot:1","l":5,"lvl":"medium","type":"expr","ctx":"Бөліндінің туындысы. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{e^x}{x}$, $y'=\\ ?$","a":"exp(x)*(x-1)/x^2"},{"id":"m4-5-quot:2","l":5,"lvl":"medium","type":"expr","ctx":"Бөліндінің туындысы. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{\\cos x}{x}$, $y'=\\ ?$","a":"(-x*sin(x)-cos(x))/x^2"},{"id":"m4-5-xlnx:0","l":5,"lvl":"medium","type":"num","ctx":"Туындының нүктедегі мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=x\\ln x$ үшін $f'(e)$.","a":2},{"id":"m4-5-xlnx:1","l":5,"lvl":"medium","type":"num","ctx":"Туындының нүктедегі мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$g(x)=\\dfrac{x}{x^2+3}$ үшін $g'(1)$.","a":"1/8"},{"id":"m4-5-rule:0","l":5,"lvl":"medium","type":"choice","ctx":"Қай ережені қолдану керек?. Дұрыс жауапты таңдаңыз.","q":"$y=x^2\\sin x$ функциясының туындысын табу үшін ең алдымен не қолданылады?","o":["көбейтінді ережесі","бөлінді ережесі","тек қосынды ережесі","анықтама бойынша шек"],"a":0,"e":"Сыртқы амал - көбейтінді."},{"id":"m4-5-rule:1","l":5,"lvl":"medium","type":"choice","ctx":"Қай ережені қолдану керек?. Дұрыс жауапты таңдаңыз.","q":"$y=\\dfrac{\\ln x}{x^2}$ үшін алғашқы қадам?","o":["көбейтінді ережесі","бөлінді ережесі","қосынды ережесі","тізбектік ереже"],"a":1,"e":"Сыртқы амал - бөлінді (алымы $\\ln x$, бөлгіші $x^2$)."},{"id":"m4-5-rule:2","l":5,"lvl":"medium","type":"choice","ctx":"Қай ережені қолдану керек?. Дұрыс жауапты таңдаңыз.","q":"Қай өрнекті алдымен ықшамдаған тиімді?","o":["$\\dfrac{x^3-x}{x}$","$x\\sin x$","$\\dfrac{e^x}{x}$","$x^2\\ln x$"],"a":0,"e":"$\\dfrac{x^3-x}{x}=x^2-1$ ($x\\ne0$), туынды $2x$."},{"id":"m4-5-trig:0","l":5,"lvl":"medium","type":"expr","ctx":"Тригонометриялық туындылар. Туындыны $x$ арқылы жазыңыз.","q":"$y=x\\tan x$, $y'=\\ ?$","a":"tan(x)+x/cos(x)^2","dom":[0.1,1.2]},{"id":"m4-5-trig:1","l":5,"lvl":"medium","type":"expr","ctx":"Тригонометриялық туындылар. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{1-\\cos x}{\\sin x}$, $y'=\\ ?$","a":"1/(1+cos(x))","dom":[0.2,2.5]},{"id":"m4-5-incr:0","l":5,"lvl":"medium","type":"interval","ctx":"Өсу аралығы. Туындының таңбасы бойынша функцияның өсетін аралығын жазыңыз (шексіздік - oo).","q":"$f(x)=xe^x$ қай аралықта өседі ($f'>0$)?","a":"(-1; oo)"},{"id":"m4-5-incr:1","l":5,"lvl":"medium","type":"interval","ctx":"Өсу аралығы. Туындының таңбасы бойынша функцияның өсетін аралығын жазыңыз (шексіздік - oo).","q":"$g(x)=\\dfrac{x}{x^2+1}$ қай аралықта өседі?","a":"(-1; 1)"},{"id":"m4-5-second:0","l":5,"lvl":"hard","type":"num","ctx":"Екінші және жоғары ретті туындылар. Жауапты санмен жазыңыз.","q":"$f(x)=x^4-3x^2+x$ үшін $f''(2)$.","a":42},{"id":"m4-5-second:1","l":5,"lvl":"hard","type":"num","ctx":"Екінші және жоғары ретті туындылар. Жауапты санмен жазыңыз.","q":"$g(x)=xe^x$ үшін $g^{(5)}(0)$.","a":5},{"id":"m4-5-second:2","l":5,"lvl":"hard","type":"num","ctx":"Екінші және жоғары ретті туындылар. Жауапты санмен жазыңыз.","q":"$h(x)=\\sin x$ үшін $h^{(10)}(\\pi/2)$.","a":-1},{"id":"m4-5-three:0","l":5,"lvl":"hard","type":"expr","ctx":"Үш көбейткіш және күрделі бөлінді. Туындыны $x$ арқылы жазыңыз.","q":"$y=x\\,e^x\\ln x$, $y'=\\ ?$","a":"exp(x)*log(x)*(1+x)+exp(x)","dom":[0.3,4]},{"id":"m4-5-three:1","l":5,"lvl":"hard","type":"expr","ctx":"Үш көбейткіш және күрделі бөлінді. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{x^2\\sin x}{1+x}$, $y'=\\ ?$","a":"((2*x*sin(x)+x^2*cos(x))*(1+x)-x^2*sin(x))/(1+x)^2","dom":[0.3,4]},{"id":"m4-5-tf2:0","l":5,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ және $g$ нүктеде дифференциалданбаса, $f+g$ да дифференциалданбайды.","a":false,"e":"Жалған: $f=|x|$, $g=-|x|$ нөлде дифференциалданбайды, ал $f+g=0$ дифференциалданады."},{"id":"m4-5-tf2:1","l":5,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ дифференциалданады, $g$ дифференциалданбайды болса, $f+g$ дифференциалданбайды.","a":true,"e":"Ақиқат: $g=(f+g)-f$ болар еді."},{"id":"m4-5-tf2:2","l":5,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$(fg)''=f''g''$.","a":false,"e":"Жалған: $(fg)''=f''g+2f'g'+fg''$."},{"id":"m4-5-tf2:3","l":5,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$x^2\\cdot x$ көбейтіндісі үшін көбейтінді ережесі де, $x^3$ дәреже ережесі де бірдей нәтиже береді.","a":true,"e":"Ақиқат: $2x\\cdot x+x^2\\cdot1=3x^2$."},{"id":"m4-5-second-expr:0","l":5,"lvl":"hard","type":"expr","ctx":"Екінші ретті туынды өрнегі. Екінші туындыны $x$ арқылы жазыңыз.","q":"$y=x\\ln x$, $y''=\\ ?$","a":"1/x","dom":[0.3,5]},{"id":"m4-5-second-expr:1","l":5,"lvl":"hard","type":"expr","ctx":"Екінші ретті туынды өрнегі. Екінші туындыны $x$ арқылы жазыңыз.","q":"$y=\\dfrac{1}{x}+x^3$, $y''=\\ ?$","a":"2/x^3+6*x","dom":[0.3,5]},{"id":"m4-5-vec:0","l":5,"lvl":"hard","type":"matrix","ctx":"Туындылар кестесі. Ұяшықтарға сандарды жазыңыз.","q":"$f(x)=x^3-3x$ үшін $\\begin{pmatrix}f'(0)&f'(1)\\\\ f'(2)&f''(2)\\end{pmatrix}$ матрицасын толтырыңыз.","name":"$M=$","a":[[-3,0],[9,12]]},{"id":"w25-q0","l":5,"lvl":"quiz","type":"choice","q":"y = (x² + 1)(3x − 2) функциясының туындысы қандай?","o":["9x² − 4x + 3","6x","2x · 3","9x² + 3"],"a":0,"e":"2x(3x − 2) + (x² + 1)·3 = 6x² − 4x + 3x² + 3 = 9x² − 4x + 3."},{"id":"w25-q1","l":5,"lvl":"quiz","type":"choice","q":"y = x/(x + 1) функциясының туындысы қандай?","o":["1","1/(x + 1)","1/(x + 1)²","(2x + 1)/(x + 1)²"],"a":2,"e":"[1·(x + 1) − x·1]/(x + 1)² = 1/(x + 1)²."},{"id":"w25-q2","l":5,"lvl":"quiz","type":"choice","q":"(tan x)' неге тең?","o":["sec x","−1/sin²x","cos x","1/cos²x"],"a":3,"e":"(sin x/cos x)' = (cos²x + sin²x)/cos²x = 1/cos²x."},{"id":"w25-q3","l":5,"lvl":"quiz","type":"choice","q":"y = x·eˣ үшін y'' неге тең?","o":["eˣ(x + 1)","eˣ(x + 2)","xeˣ","eˣ(x + 3)"],"a":1,"e":"y' = eˣ(x + 1), y'' = eˣ(x + 1) + eˣ = eˣ(x + 2)."},{"id":"w25-q4","l":5,"lvl":"quiz","type":"choice","q":"(x² · x)' үшін көбейтінді ережесі қандай нәтиже береді?","o":["3x²","2x","2x²","x²"],"a":0,"e":"2x·x + x²·1 = 3x², және x³-тің туындысы да 3x²."},{"id":"w25-q5","l":5,"lvl":"quiz","type":"choice","q":"y = x ln x функциясы үшін y'(e) неге тең?","o":["1","e","2","e + 1"],"a":2,"e":"y' = ln x + 1, y'(e) = 1 + 1 = 2."},{"id":"w25-q6","l":5,"lvl":"quiz","type":"choice","q":"sin x функциясының 10-шы ретті туындысы x = π/2 нүктесінде неге тең?","o":["1","0","10","−1"],"a":3,"e":"(sin x)⁽¹⁰⁾ = sin(x + 5π) = −sin x, x = π/2 үшін −1."},{"id":"w25-q7","l":5,"lvl":"quiz","type":"choice","q":"Қай пікір қате?","o":["(f + g)' = f' + g'","(f/g)' = f'/g'","(c·f)' = c·f'","(fg)' = f'g + fg'"],"a":1,"e":"Бөлінді ережесі (f/g)' = (f'g − fg')/g². (f/g)' = f'/g' қате."},{"id":"m4-6-values:0","l":6,"lvl":"easy","type":"num","ctx":"Құрама функцияның туындысының мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$y=(2x+3)^4$ үшін $y'(0)$.","a":216},{"id":"m4-6-values:1","l":6,"lvl":"easy","type":"num","ctx":"Құрама функцияның туындысының мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$y=\\sin3x$ үшін $y'(0)$.","a":3},{"id":"m4-6-values:2","l":6,"lvl":"easy","type":"num","ctx":"Құрама функцияның туындысының мәні. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$y=\\ln(1+x^2)$ үшін $y'(1)$.","a":1},{"id":"m4-6-tf:0","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\sin3x)'=\\cos3x$.","a":false,"e":"Жалған: $(\\sin3x)'=3\\cos3x$ (ішкі функцияның туындысы көбейтіледі)."},{"id":"m4-6-tf:1","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(e^{2x})'=2e^{2x}$.","a":true,"e":"Ақиқат: $(e^u)'=u'e^u$."},{"id":"m4-6-tf:2","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\ln x^2)'=\\dfrac{1}{x^2}$.","a":false,"e":"Жалған: $(\\ln x^2)'=\\dfrac{2x}{x^2}=\\dfrac2x$."},{"id":"m4-6-tf:3","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$(\\arctan x)'=\\dfrac{1}{1+x^2}$.","a":true,"e":"Ақиқат: 3-қорытудың нәтижесі."},{"id":"m4-6-tf:4","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\sin^2x$ және $\\sin x^2$ бірдей функция.","a":false,"e":"Жалған: $\\sin^2x=(\\sin x)^2$, $\\sin x^2=\\sin(x^2)$; туындылары $2\\sin x\\cos x$ және $2x\\cos x^2$."},{"id":"m4-6-chain1:0","l":6,"lvl":"easy","type":"expr","ctx":"Бір қабатты құрама. Туындыны $x$ арқылы жазыңыз.","q":"$y=(3x-1)^5$, $y'=\\ ?$","a":"15*(3*x-1)^4"},{"id":"m4-6-chain1:1","l":6,"lvl":"easy","type":"expr","ctx":"Бір қабатты құрама. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\sqrt{x^2+1}$, $y'=\\ ?$","a":"x/sqrt(x^2+1)"},{"id":"m4-6-chain2:0","l":6,"lvl":"medium","type":"expr","ctx":"Тригонометриялық, көрсеткіштік және логарифмдік. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\cos(3x+1)$, $y'=\\ ?$","a":"-3*sin(3*x+1)"},{"id":"m4-6-chain2:1","l":6,"lvl":"medium","type":"expr","ctx":"Тригонометриялық, көрсеткіштік және логарифмдік. Туындыны $x$ арқылы жазыңыз.","q":"$y=e^{-x^2}$, $y'=\\ ?$","a":"-2*x*exp(-x^2)"},{"id":"m4-6-chain2:2","l":6,"lvl":"medium","type":"expr","ctx":"Тригонометриялық, көрсеткіштік және логарифмдік. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\ln(x^2+1)$, $y'=\\ ?$","a":"2*x/(x^2+1)"},{"id":"m4-6-chain3:0","l":6,"lvl":"medium","type":"expr","ctx":"Көп қабатты құрама. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\sin^2(3x)$, $y'=\\ ?$","a":"6*sin(3*x)*cos(3*x)"},{"id":"m4-6-chain3:1","l":6,"lvl":"medium","type":"expr","ctx":"Көп қабатты құрама. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\ln(\\sin x)$, $y'=\\ ?$","a":"cos(x)/sin(x)","dom":[0.3,2.8]},{"id":"m4-6-chain3:2","l":6,"lvl":"medium","type":"expr","ctx":"Көп қабатты құрама. Туындыны $x$ арқылы жазыңыз.","q":"$y=e^{\\sin x}$, $y'=\\ ?$","a":"exp(sin(x))*cos(x)"},{"id":"m4-6-implicit:0","l":6,"lvl":"medium","type":"num","ctx":"Айқын емес функцияның туындысы. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$x^2+y^2=25$ шеңберінің $(3;4)$ нүктесіндегі жанамасының еңісі.","a":"-3/4"},{"id":"m4-6-implicit:1","l":6,"lvl":"medium","type":"num","ctx":"Айқын емес функцияның туындысы. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$x^2+xy+y^2=7$ қисығының $(2;1)$ нүктесіндегі $y'$.","a":"-5/4"},{"id":"m4-6-implicit:2","l":6,"lvl":"medium","type":"num","ctx":"Айқын емес функцияның туындысы. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$e^y+xy=e$ теңдеуінің $(0;1)$ нүктесіндегі $y'$.","a":"-1/e"},{"id":"m4-6-structure:0","l":6,"lvl":"medium","type":"choice","ctx":"Құрамның құрылымы. Дұрыс жауапты таңдаңыз.","q":"$y=\\sin(e^{x^2})$ функциясының туындысында қанша көбейткіш (қабат) болады?","o":["бір: $\\cos(e^{x^2})$","екі: $\\cos(e^{x^2})\\cdot e^{x^2}$","үш: $\\cos(e^{x^2})\\cdot e^{x^2}\\cdot2x$","төрт"],"a":2,"e":"Қабаттар: синус → $e^{(\\cdot)}$ → $x^2$. Әрқайсысының туындысы көбейтіледі."},{"id":"m4-6-structure:1","l":6,"lvl":"medium","type":"choice","ctx":"Құрамның құрылымы. Дұрыс жауапты таңдаңыз.","q":"$y=\\dfrac{1}{\\sqrt{x^2+4}}$ үшін ең тиімді жазу?","o":["$y=(x^2+4)^{-1/2}$ деп тізбектік ережені қолдану","бөлінді ережесі","көбейтінді ережесі","анықтамадан шек"],"a":0,"e":"$(u^{-1/2})'=-\\frac12u^{-3/2}u'$, нәтиже $-\\dfrac{x}{(x^2+4)^{3/2}}$."},{"id":"m4-6-inverse:0","l":6,"lvl":"medium","type":"num","ctx":"Кері функцияның туындысы. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"$f(x)=x^3+x$ үшін $(f^{-1})'(10)$ ($f(2)=10$).","a":"1/13"},{"id":"m4-6-inverse:1","l":6,"lvl":"medium","type":"num","ctx":"Кері функцияның туындысы. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"$f(x)=2x+\\sin x$ үшін $(f^{-1})'(0)$ ($f(0)=0$).","a":"1/3"},{"id":"m4-6-inverse:2","l":6,"lvl":"medium","type":"num","ctx":"Кері функцияның туындысы. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"$f(x)=e^x+x$ үшін $(f^{-1})'(1)$ ($f(0)=1$).","a":"1/2"},{"id":"m4-6-arc:0","l":6,"lvl":"medium","type":"expr","ctx":"Кері тригонометриялық функциялар. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\arctan(2x)$, $y'=\\ ?$","a":"2/(1+4*x^2)"},{"id":"m4-6-arc:1","l":6,"lvl":"medium","type":"expr","ctx":"Кері тригонометриялық функциялар. Туындыны $x$ арқылы жазыңыз.","q":"$y=\\arcsin\\dfrac x2$, $y'=\\ ?$ ($|x|< 2$)","a":"1/sqrt(4-x^2)","dom":[-1.8,1.8]},{"id":"m4-6-arc:2","l":6,"lvl":"medium","type":"expr","ctx":"Кері тригонометриялық функциялар. Туындыны $x$ арқылы жазыңыз.","q":"$y=x\\arctan x$, $y'=\\ ?$","a":"atan(x)+x/(1+x^2)"},{"id":"m4-6-domain:0","l":6,"lvl":"medium","type":"interval","ctx":"Туындының бар болу облысы. Туынды бар болатын облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$y=\\arcsin x$ функциясының туындысы бар $x$ жиыны.","a":"(-1; 1)"},{"id":"m4-6-domain:1","l":6,"lvl":"medium","type":"interval","ctx":"Туындының бар болу облысы. Туынды бар болатын облысты аралық түрінде жазыңыз (шексіздік - oo, бірігу - U).","q":"$y=\\sqrt{x^2-4}$ функциясының туындысы бар $x$ жиыны.","a":"(-oo; -2) U (2; oo)"},{"id":"m4-6-logdiff:0","l":6,"lvl":"hard","type":"expr","ctx":"Логарифмдік дифференциалдау. Туындыны $x$ арқылы жазыңыз ($x>0$).","q":"$y=x^x$, $y'=\\ ?$","a":"x^x*(ln(x)+1)","dom":[0.3,3]},{"id":"m4-6-logdiff:1","l":6,"lvl":"hard","type":"expr","ctx":"Логарифмдік дифференциалдау. Туындыны $x$ арқылы жазыңыз ($x>0$).","q":"$y=x^{\\sin x}$, $y'=\\ ?$","a":"x^sin(x)*(cos(x)*ln(x)+sin(x)/x)","dom":[0.3,3]},{"id":"m4-6-logdiff:2","l":6,"lvl":"hard","type":"expr","ctx":"Логарифмдік дифференциалдау. Туындыны $x$ арқылы жазыңыз ($x>0$).","q":"$y=(\\ln x)^x$, $y'=\\ ?$ ($x>1$)","a":"(ln(x))^x*(ln(ln(x))+1/ln(x))","dom":[1.5,4]},{"id":"m4-6-xx:0","l":6,"lvl":"hard","type":"num","ctx":"Күрделі туындының мәні. Жауапты санмен жазыңыз (ондық бөлшек не $\\ln$ арқылы).","q":"$y=x^x$ үшін $y'(2)$. ($\\ln2\\approx0{,}6931$)","a":"4*(ln(2)+1)","tol":0.001},{"id":"m4-6-xx:1","l":6,"lvl":"hard","type":"num","ctx":"Күрделі туындының мәні. Жауапты санмен жазыңыз (ондық бөлшек не $\\ln$ арқылы).","q":"$y=\\arctan(x^2)$ үшін $y'(1)$.","a":1},{"id":"m4-6-tf2:0","l":6,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ және $g$ жұп функциялар болса, $(f\\circ g)'$ тақ функция.","a":true,"e":"Ақиқат: $f(g(-x))=f(g(x))$, яғни $f\\circ g$ жұп, ал жұп функцияның туындысы тақ."},{"id":"m4-6-tf2:1","l":6,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ жұп функция болса, $f'$ тақ функция.","a":true,"e":"Ақиқат: $f(-x)=f(x)$ теңдігін дифференциалдасақ, $-f'(-x)=f'(x)$, яғни $f'(-x)=-f'(x)$."},{"id":"m4-6-tf2:2","l":6,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ тақ функция болса, $f'$ жұп функция.","a":true,"e":"Ақиқат: $f(-x)=-f(x)$, дифференциалдасақ $-f'(-x)=-f'(x)$, яғни $f'(-x)=f'(x)$."},{"id":"m4-6-tf2:3","l":6,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f^{-1}$ функциясының графигінде жанаманың еңісі әрдайым $f$ графигіндегі сәйкес жанаманың еңісінің кері шамасы.","a":true,"e":"Ақиқат: $(f^{-1})'(y_0)=1/f'(x_0)$, $f'(x_0)\\ne0$ болғанда. Графиктер $y=x$ бойынша симметриялы."},{"id":"m4-6-vec:0","l":6,"lvl":"hard","type":"matrix","ctx":"Үш функцияның туындыларының мәні. Вектордың компоненттерін сандармен жазыңыз.","q":"$x=1$ нүктесінде $\\sqrt{x^2+3}$, $(2x-1)^3$, $\\dfrac{1}{x^2+1}$ функцияларының туындыларының мәндерін баған-вектор түрінде жазыңыз.","name":"$\\mathbf{d}=$","a":["1/2","6","-1/2"]},{"id":"w26-q0","l":6,"lvl":"quiz","type":"choice","q":"y = sin(3x) функциясының туындысы қандай?","o":["cos(3x)","3cos(3x)","−3cos(3x)","3sin(3x)"],"a":1,"e":"(sin u)' = u'·cos u, u = 3x, u' = 3."},{"id":"w26-q1","l":6,"lvl":"quiz","type":"choice","q":"y = ln(x² + 1) функциясының туындысы қандай?","o":["1/(x² + 1)","2x","1/x","2x/(x² + 1)"],"a":3,"e":"(ln u)' = u'/u = 2x/(x² + 1)."},{"id":"w26-q2","l":6,"lvl":"quiz","type":"choice","q":"f(x) = x³ + 2x үшін (f⁻¹)'(3) неге тең? (f(1) = 3)","o":["1/5","5","1/3","3"],"a":0,"e":"f'(x) = 3x² + 2, f'(1) = 5. (f⁻¹)'(3) = 1/f'(1) = 1/5."},{"id":"w26-q3","l":6,"lvl":"quiz","type":"choice","q":"x² + y² = 25 шеңберінің (3; 4) нүктесіндегі жанамасының еңісі қанша?","o":["3/4","4/3","−3/4","−4/3"],"a":2,"e":"2x + 2yy' = 0 ⇒ y' = −x/y = −3/4."},{"id":"w26-q4","l":6,"lvl":"quiz","type":"choice","q":"(arctan x)' неге тең?","o":["1/√(1 − x²)","1/(1 + x²)","−1/(1 + x²)","1/(1 − x²)"],"a":1,"e":"x = tan y болса, dx/dy = 1 + tan²y = 1 + x², сондықтан y' = 1/(1 + x²)."},{"id":"w26-q5","l":6,"lvl":"quiz","type":"choice","q":"y = x^x (x > 0) функциясының туындысы қандай?","o":["x·x^(x−1)","x^x","x^x·ln x","x^x(ln x + 1)"],"a":3,"e":"ln y = x ln x ⇒ y'/y = ln x + 1."},{"id":"w26-q6","l":6,"lvl":"quiz","type":"choice","q":"y = e^(−x²) функциясының туындысы қандай?","o":["−2x·e^(−x²)","e^(−x²)","2x·e^(−x²)","−x²·e^(−x²−1)"],"a":0,"e":"(e^u)' = u'e^u, u = −x², u' = −2x."},{"id":"w26-q7","l":6,"lvl":"quiz","type":"choice","q":"x = t − sin t, y = 1 − cos t болса, t = π/2 кезінде dy/dx неге тең?","o":["0","−1","1","∞"],"a":2,"e":"dy/dx = sin t/(1 − cos t); t = π/2: 1/(1 − 0) = 1."},{"id":"m4-7-lh1:0","l":7,"lvl":"easy","type":"num","ctx":"Лопиталь ережесі: бір қадам. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin5x}{3x}$","a":"5/3"},{"id":"m4-7-lh1:1","l":7,"lvl":"easy","type":"num","ctx":"Лопиталь ережесі: бір қадам. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to1}\\frac{x^3-1}{x^2-1}$","a":"3/2"},{"id":"m4-7-lh1:2","l":7,"lvl":"easy","type":"num","ctx":"Лопиталь ережесі: бір қадам. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\frac{e^{2x}-1}{x}$","a":2},{"id":"m4-7-tf:0","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Ролль теоремасында $f(a)=f(b)$ шарты қажет.","a":true,"e":"Ақиқат: онсыз туынды барлық жерде нөлден өзгеше болуы мүмкін ($f(x)=x$)."},{"id":"m4-7-tf:1","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Лопиталь ережесін кез келген шекке қолдануға болады.","a":false,"e":"Жалған: түрі $\\frac00$ не $\\frac\\infty\\infty$ болуы керек, туындылар қатынасының шегі бар болуы тиіс."},{"id":"m4-7-tf:2","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f'(c)=0$ болса, $c$ міндетті түрде экстремум нүктесі.","a":false,"e":"Жалған: $f(x)=x^3$, $c=0$."},{"id":"m4-7-tf:3","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Туындысы әр жерде нөл болатын функция тұрақты (аралықта).","a":true,"e":"Ақиқат: Лагранж теоремасының салдары."},{"id":"m4-7-tf:4","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Лагранж теоремасындағы $c$ әрдайым кесіндінің ортасы.","a":false,"e":"Жалған: $\\sqrt x$, $[1;9]$ үшін $c=4$, ал орта 5."},{"id":"m4-7-cond:0","l":7,"lvl":"easy","type":"choice","ctx":"Теорема шарттары. Дұрыс жауапты таңдаңыз.","q":"Қай функция үшін $[-1;1]$ кесіндісінде Ролль теоремасы қолданылмайды?","o":["$x^2$","$|x|$","$x^3-x$","$\\cos(\\pi x/2)$"],"a":1,"e":"$|x|$ нөлде дифференциалданбайды."},{"id":"m4-7-cond:1","l":7,"lvl":"easy","type":"choice","ctx":"Теорема шарттары. Дұрыс жауапты таңдаңыз.","q":"Лагранж теоремасында $f(x)=x^2$, $[1;3]$ үшін $c$ неге тең?","o":["$1$","$2$","$3$","$1{,}5$"],"a":1,"e":"Қиюшы еңісі $\\frac{9-1}{2}=4=2c$, $c=2$."},{"id":"m4-7-cond:2","l":7,"lvl":"easy","type":"choice","ctx":"Теорема шарттары. Дұрыс жауапты таңдаңыз.","q":"Қай шекке Лопиталь ережесін қолдануға болады?","o":["$\\lim_{x\\to0}\\frac{x+2}{x+1}$","$\\lim_{x\\to0}\\frac{\\sin x}{x}$","$\\lim_{x\\to\\infty}\\frac{2x+1}{3}$","$\\lim_{x\\to2}\\frac{x}{x+1}$"],"a":1,"e":"Тек екіншісі $\\frac00$ түрінде."},{"id":"m4-7-mvt:0","l":7,"lvl":"medium","type":"num","ctx":"Орта мән нүктесін табу. Лагранж теоремасындағы $c$ нүктесін табыңыз. Жауапты ондық бөлшекпен жазыңыз.","q":"$f(x)=x^2$, $[1;4]$ кесіндісінде $c$ неге тең?","a":2.5},{"id":"m4-7-mvt:1","l":7,"lvl":"medium","type":"num","ctx":"Орта мән нүктесін табу. Лагранж теоремасындағы $c$ нүктесін табыңыз. Жауапты ондық бөлшекпен жазыңыз.","q":"$f(x)=x^3$, $[0;2]$ кесіндісінде $c$ ($c>0$) неге тең?","a":"2/sqrt(3)"},{"id":"m4-7-mvt:2","l":7,"lvl":"medium","type":"num","ctx":"Орта мән нүктесін табу. Лагранж теоремасындағы $c$ нүктесін табыңыз. Жауапты ондық бөлшекпен жазыңыз.","q":"$f(x)=\\sqrt x$, $[1;9]$ кесіндісінде $c$.","a":4},{"id":"m4-7-lh2:0","l":7,"lvl":"medium","type":"num","ctx":"Екі рет Лопиталь. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\frac{1-\\cos x}{x^2}$","a":"1/2"},{"id":"m4-7-lh2:1","l":7,"lvl":"medium","type":"num","ctx":"Екі рет Лопиталь. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\sin x-x}{x^3}$","a":"-1/6"},{"id":"m4-7-lh2:2","l":7,"lvl":"medium","type":"num","ctx":"Екі рет Лопиталь. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\frac{\\tan x-x}{x^3}$","a":"1/3"},{"id":"m4-7-inf:0","l":7,"lvl":"medium","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{\\ln x}{\\sqrt x}$","a":0},{"id":"m4-7-inf:1","l":7,"lvl":"medium","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{x^3}{e^{2x}}$","a":0},{"id":"m4-7-inf:2","l":7,"lvl":"medium","type":"num","ctx":"Шексіздіктегі шектер. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{x^{10}}{e^x}$","a":0},{"id":"m4-7-pow:0","l":7,"lvl":"medium","type":"num","ctx":"Дәрежелі анықталмағандықтар. Жауапты санмен немесе $e$ арқылы жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0^+}x^{x}$","a":1},{"id":"m4-7-pow:1","l":7,"lvl":"medium","type":"num","ctx":"Дәрежелі анықталмағандықтар. Жауапты санмен немесе $e$ арқылы жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}(\\cos x)^{1/x^2}$","a":"exp(-1/2)"},{"id":"m4-7-pow:2","l":7,"lvl":"medium","type":"num","ctx":"Дәрежелі анықталмағандықтар. Жауапты санмен немесе $e$ арқылы жазыңыз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\left(1+\\dfrac2x\\right)^{x}$","a":"exp(2)"},{"id":"m4-7-mono:0","l":7,"lvl":"medium","type":"interval","ctx":"Монотондылық аралығы. Теорема 7.5 арқылы функцияның кемитін аралығын жазыңыз (шексіздік - oo).","q":"$f(x)=x^3-3x$ функциясы қай аралықта кемиді?","a":"(-1; 1)"},{"id":"m4-7-mono:1","l":7,"lvl":"medium","type":"interval","ctx":"Монотондылық аралығы. Теорема 7.5 арқылы функцияның кемитін аралығын жазыңыз (шексіздік - oo).","q":"$g(x)=xe^{-x}$ функциясы қай аралықта кемиді?","a":"(1; oo)"},{"id":"m4-7-simplify:0","l":7,"lvl":"medium","type":"expr","ctx":"Туындылар қатынасы. Лопиталь ережесінің қадамындағы $\\dfrac{f'}{g'}$ өрнегін ықшам түрде жазыңыз.","q":"$\\dfrac{f}{g}=\\dfrac{e^x-1-x}{x^2}$ үшін $\\dfrac{f'}{g'}=\\ ?$","a":"(exp(x)-1)/(2*x)","dom":[0.3,2]},{"id":"m4-7-simplify:1","l":7,"lvl":"medium","type":"expr","ctx":"Туындылар қатынасы. Лопиталь ережесінің қадамындағы $\\dfrac{f'}{g'}$ өрнегін ықшам түрде жазыңыз.","q":"$\\dfrac{f}{g}=\\dfrac{\\ln x}{\\sqrt x}$ үшін $\\dfrac{f'}{g'}=\\ ?$ ($x>0$)","a":"2/sqrt(x)","dom":[0.3,5]},{"id":"m4-7-inf-inf:0","l":7,"lvl":"hard","type":"num","ctx":"∞ − ∞ түрін ашу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\left(\\frac1x-\\frac{1}{e^x-1}\\right)$","a":"1/2"},{"id":"m4-7-inf-inf:1","l":7,"lvl":"hard","type":"num","ctx":"∞ − ∞ түрін ашу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to0}\\left(\\frac{1}{\\sin x}-\\frac1x\\right)$","a":0},{"id":"m4-7-inf-inf:2","l":7,"lvl":"hard","type":"num","ctx":"∞ − ∞ түрін ашу. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\lim_{x\\to1}\\left(\\frac{1}{\\ln x}-\\frac{1}{x-1}\\right)$","a":"1/2"},{"id":"m4-7-tangent-par:0","l":7,"lvl":"hard","type":"expr","ctx":"Параллель жанаманы табу. Лагранж теоремасы бойынша жанама мен қиюшы параллель. Жанама теңдеуін жазыңыз.","q":"$f(x)=x^2$ параболасы үшін $A(1;1)$ және $B(3;9)$ нүктелері арқылы өтетін қиюшыға параллель жанама теңдеуі.","eq":true,"a":"y=4*x-4"},{"id":"m4-7-tf2:0","l":7,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$\\displaystyle\\lim_{x\\to\\infty}\\frac{x-\\sin x}{x+\\sin x}=1$, және Лопиталь ережесін қолдануға болады.","a":false,"e":"Шек шынымен 1 ($\\frac{1-\\sin x/x}{1+\\sin x/x}\\to1$). Бірақ Лопиталь ережесі жарамсыз: $\\frac{1-\\cos x}{1+\\cos x}$ шегі жоқ. Сондықтан пікірдің екінші бөлігі жалған."},{"id":"m4-7-tf2:1","l":7,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ дифференциалданады және $|f'(x)|\\le1$ болса, $|f(x)-f(y)|\\le|x-y|$.","a":true,"e":"Ақиқат: Лагранж теоремасының салдары (Липшиц бағасы)."},{"id":"m4-7-tf2:2","l":7,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f'(x)>0$ аралықта болса, $f$ қатаң өспелі, және керісінше: қатаң өспелі функцияның туындысы әрдайым оң.","a":false,"e":"Жалған: $f(x)=x^3$ қатаң өспелі, бірақ $f'(0)=0$."},{"id":"m4-7-tf2:3","l":7,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$e^x\\ge1+x$ барлық нақты $x$ үшін.","a":true,"e":"Ақиқат: 5-қорыту."},{"id":"m4-7-ratios:0","l":7,"lvl":"hard","type":"matrix","ctx":"Қатынастар тізбегі. Ұяшықтарға сандарды жазыңыз.","q":"$\\dfrac{f}{g}$, $\\dfrac{f'}{g'}$, $\\dfrac{f''}{g''}$ өрнектерінің $x=1$ нүктесіндегі мәндерін жол түрінде жазыңыз ($f=e^x-1-x$, $g=x^2$; ондық бөлшекпен 3 таңбаға дейін).","orient":"row","name":"мәндер:","a":["e-2","(e-1)/2","e/2"],"tol":0.002},{"id":"m4-7-ineq:0","l":7,"lvl":"hard","type":"num","ctx":"Лагранж арқылы бағалау. Жауапты ондық бөлшекпен жазыңыз.","q":"$\\dfrac{b-a}{b}<\\ln\\dfrac ba$ теңсіздігіне $a=2$, $b=3$ қойыңыз. Сол жақ бөлігі неге тең?","a":"1/3"},{"id":"m4-7-ineq:1","l":7,"lvl":"hard","type":"num","ctx":"Лагранж арқылы бағалау. Жауапты ондық бөлшекпен жазыңыз.","q":"$\\ln\\dfrac ba<\\dfrac{b-a}{a}$ теңсіздігіне $a=2$, $b=3$ қойыңыз. Оң жағы неге тең?","a":"1/2"},{"id":"w27-q0","l":7,"lvl":"quiz","type":"choice","q":"lim (x → 0) (e^x − 1 − x)/x² неге тең?","o":["0","1","1/2","∞"],"a":2,"e":"0/0: (e^x − 1)/(2x) — тағы 0/0, e^x/2 → 1/2."},{"id":"w27-q1","l":7,"lvl":"quiz","type":"choice","q":"f(x) = x², [1; 3] кесіндісінде Лагранж теоремасындағы c неге тең?","o":["2","1,5","2,5","3"],"a":0,"e":"Қиюшы еңісі (9 − 1)/2 = 4 = f'(c) = 2c, c = 2."},{"id":"w27-q2","l":7,"lvl":"quiz","type":"choice","q":"Қай жағдайда Ролль теоремасы [−1; 1] кесіндісінде қолданылмайды?","o":["f(x) = x² − 1","f(x) = cos(πx/2)","f(x) = x³ − x","f(x) = |x|"],"a":3,"e":"|x| нөлде дифференциалданбайды, сондықтан шарт бұзылған."},{"id":"w27-q3","l":7,"lvl":"quiz","type":"choice","q":"lim (x → 0⁺) x ln x неге тең?","o":["−∞","0","1","−1"],"a":1,"e":"x ln x = ln x/(1/x), Лопиталь: (1/x)/(−1/x²) = −x → 0."},{"id":"w27-q4","l":7,"lvl":"quiz","type":"choice","q":"Қай шекке Лопиталь ережесі жарамсыз?","o":["lim (x → 0) sin x/x","lim (x → ∞) ln x/x","lim (x → ∞) (x + sin x)/x","lim (x → 0) (1 − cos x)/x²"],"a":2,"e":"Туындылар қатынасы 1 + cos x шегі жоқ, ал бастапқы шек 1. Қалғандарында ереже жұмыс істейді."},{"id":"w27-q5","l":7,"lvl":"quiz","type":"choice","q":"lim (x → 0) (cos x)^(1/x²) неге тең?","o":["e^(−1/2)","1","e^(1/2)","0"],"a":0,"e":"ln cos x/x² → (−tan x)/(2x) → −1/2, шек e^(−1/2)."},{"id":"w27-q6","l":7,"lvl":"quiz","type":"choice","q":"f'(x) = 0 барлық x ∈ (a; b) үшін болса, f қандай?","o":["өспелі","кемімелі","үзілісті","тұрақты"],"a":3,"e":"Лагранж: f(x₂) − f(x₁) = f'(c)(x₂ − x₁) = 0."},{"id":"w27-q7","l":7,"lvl":"quiz","type":"choice","q":"Ферма теоремасына сәйкес, жергілікті экстремум нүктесінде (туынды бар болса) не орындалады?","o":["f'(c) > 0","f'(c) = 0","f'(c) < 0","f(c) = 0"],"a":1,"e":"Оң және сол жақты айырымдық қатынастар әртүрлі таңбада, сондықтан шек нөл."},{"id":"m4-8-crit:0","l":8,"lvl":"easy","type":"num","ctx":"Критикалық нүктелер. Жауапты санмен жазыңыз.","q":"$f(x)=x^2-6x+5$ функциясының критикалық нүктесі.","a":3},{"id":"m4-8-crit:1","l":8,"lvl":"easy","type":"num","ctx":"Критикалық нүктелер. Жауапты санмен жазыңыз.","q":"$f(x)=x^3-12x$ функциясының оң критикалық нүктесі.","a":2},{"id":"m4-8-crit:2","l":8,"lvl":"easy","type":"num","ctx":"Критикалық нүктелер. Жауапты санмен жазыңыз.","q":"$f(x)=x^2-6x+5$ функциясының ең кіші мәні.","a":-4},{"id":"m4-8-tf:0","l":8,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f'>0$ аралықта болса, $f$ сол аралықта өседі.","a":true,"e":"Ақиқат: Теорема 8.1."},{"id":"m4-8-tf:1","l":8,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f'(c)=0$ болса, $c$ — міндетті түрде экстремум.","a":false,"e":"Жалған: $x^3$ нөлде."},{"id":"m4-8-tf:2","l":8,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Кесіндіде үзіліссіз функцияның ең үлкен мәні тек туындысы нөл нүктеде болады.","a":false,"e":"Жалған: ол кесіндінің ұшында да болуы мүмкін."},{"id":"m4-8-tf:3","l":8,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f''>0$ болса, график төмен дөңес (жанамадан жоғары).","a":true,"e":"Ақиқат: Теорема 8.4."},{"id":"m4-8-tf:4","l":8,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$y=\\dfrac{x^2}{x-1}$ функциясының көлбеу асимптотасы $y=x+1$.","a":true,"e":"Ақиқат: $k=1$, $b=1$."},{"id":"m4-8-mono:0","l":8,"lvl":"medium","type":"interval","ctx":"Монотондылық аралықтары. Аралықты жазыңыз (шексіздік - oo, бірігу - U).","q":"$f(x)=x^3-3x$ функциясы өсетін жиын.","a":"(-oo; -1) U (1; oo)"},{"id":"m4-8-mono:1","l":8,"lvl":"medium","type":"interval","ctx":"Монотондылық аралықтары. Аралықты жазыңыз (шексіздік - oo, бірігу - U).","q":"$g(x)=x^4-2x^2$ функциясы кемитін жиын.","a":"(-oo; -1) U (0; 1)"},{"id":"m4-8-conv:0","l":8,"lvl":"medium","type":"interval","ctx":"Дөңестік аралықтары. Функция төмен дөңес ($f''>0$) болатын жиынды жазыңыз.","q":"$f(x)=x^4-6x^2$","a":"(-oo; -1) U (1; oo)"},{"id":"m4-8-conv:1","l":8,"lvl":"medium","type":"interval","ctx":"Дөңестік аралықтары. Функция төмен дөңес ($f''>0$) болатын жиынды жазыңыз.","q":"$g(x)=x^3-3x^2$","a":"(1; oo)"},{"id":"m4-8-second:0","l":8,"lvl":"medium","type":"expr","ctx":"Екінші туынд. Екінші туындыны $x$ арқылы жазыңыз.","q":"$f(x)=\\dfrac{x^2}{x-1}$, $f''=\\ ?$","a":"2/(x-1)^3","dom":[1.3,4]},{"id":"m4-8-second:1","l":8,"lvl":"medium","type":"expr","ctx":"Екінші туынд. Екінші туындыны $x$ арқылы жазыңыз.","q":"$f(x)=xe^{-x}$, $f''=\\ ?$","a":"exp(-x)*(x-2)"},{"id":"m4-8-asym:0","l":8,"lvl":"medium","type":"num","ctx":"Көлбеу асимптота коэффициенттері. Жауапты санмен жазыңыз.","q":"$f(x)=\\dfrac{2x^2+1}{x}$ үшін $k=\\lim\\dfrac{f(x)}{x}$.","a":2},{"id":"m4-8-asym:1","l":8,"lvl":"medium","type":"num","ctx":"Көлбеу асимптота коэффициенттері. Жауапты санмен жазыңыз.","q":"Сол функция үшін $b=\\lim(f(x)-kx)$.","a":0},{"id":"m4-8-asym:2","l":8,"lvl":"medium","type":"num","ctx":"Көлбеу асимптота коэффициенттері. Жауапты санмен жазыңыз.","q":"$g(x)=\\dfrac{x^2+x+1}{x+1}$ үшін асимптота $y=kx+b$; $b$ неге тең?","a":0},{"id":"m4-8-closed:0","l":8,"lvl":"medium","type":"num","ctx":"Кесіндідегі ең үлкен және ең кіші мән. Жауапты санмен жазыңыз.","q":"$f(x)=x^3-3x$, $[-2;2]$ кесіндісіндегі ең үлкен мән.","a":2},{"id":"m4-8-closed:1","l":8,"lvl":"medium","type":"num","ctx":"Кесіндідегі ең үлкен және ең кіші мән. Жауапты санмен жазыңыз.","q":"$g(x)=x^2-4x+5$, $[0;5]$ кесіндісіндегі ең үлкен мән.","a":10},{"id":"m4-8-closed:2","l":8,"lvl":"medium","type":"num","ctx":"Кесіндідегі ең үлкен және ең кіші мән. Жауапты санмен жазыңыз.","q":"$h(x)=x+\\dfrac{4}{x}$, $[1;4]$ кесіндісіндегі ең кіші мән.","a":4},{"id":"m4-8-types:0","l":8,"lvl":"medium","type":"choice","ctx":"Екінші белгі. Дұрыс жауапты таңдаңыз.","q":"$f(x)=x^3-3x$ функциясы үшін $x=1$ нүктесі?","o":["жергілікті максимум","жергілікті минимум","иілу нүктесі","экстремум емес"],"a":1,"e":"$f'(1)=0$, $f''(1)=6>0$: минимум."},{"id":"m4-8-types:1","l":8,"lvl":"medium","type":"choice","ctx":"Екінші белгі. Дұрыс жауапты таңдаңыз.","q":"$f(x)=x^4$ функциясы үшін екінші белгі $x=0$ нүктесінде не береді?","o":["минимум","максимум","жауап бермейді ($f''(0)=0$)","иілу нүктесі"],"a":2,"e":"$f''(0)=0$, белгі жауап бермейді; бірінші белгі бойынша нөл — минимум."},{"id":"m4-8-types:2","l":8,"lvl":"medium","type":"choice","ctx":"Екінші белгі. Дұрыс жауапты таңдаңыз.","q":"Қай функцияның нөлде иілу нүктесі бар?","o":["$x^2$","$x^3$","$x^4$","$|x|$"],"a":1,"e":"$(x^3)''=6x$ нөлден өтіп таңба ауыстырады."},{"id":"m4-8-profit:0","l":8,"lvl":"hard","type":"num","ctx":"Экономикалық оңтайландыру. Жауапты санмен жазыңыз.","q":"Сұраныс $p=120-q$, шығын $C(q)=30q+400$. Пайданы ең көбейтетін $q$.","a":45},{"id":"m4-8-profit:1","l":8,"lvl":"hard","type":"num","ctx":"Экономикалық оңтайландыру. Жауапты санмен жазыңыз.","q":"Сол пайданың ең үлкен мәні.","a":1625},{"id":"m4-8-fn:0","l":8,"lvl":"hard","type":"expr","ctx":"Мақсат функциясын құру. Мақсат функциясын бір айнымалы арқылы жазыңыз.","q":"Көлемі 54 см³ квадрат табанды жабық қораптың бет ауданы $S$ табан қабырғасы $x$ арқылы: $S(x)=\\ ?$ (биіктік $h=\\frac{54}{x^2}$).","a":"2*x^2+216/x","dom":[0.5,6]},{"id":"m4-8-fn:1","l":8,"lvl":"hard","type":"expr","ctx":"Мақсат функциясын құру. Мақсат функциясын бір айнымалы арқылы жазыңыз.","q":"Периметрі 40 тікбұрыштың бір қабырғасы $x$ болғанда ауданы $A(x)=\\ ?$","a":"x*(20-x)","dom":[0.5,19]},{"id":"m4-8-tf2:0","l":8,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"Бір ғана критикалық нүктесі бар, ол нүктеде жергілікті максимумы бар үзіліссіз функцияның сол нүктеде ғаламдық максимумы да бар (бүкіл $\\mathbb{R}$-де).","a":true,"e":"Ақиқат: функция нүктеден солға қарай өседі, оңға қарай кемиді (бір критикалық нүкте, таңба ауысады)."},{"id":"m4-8-tf2:1","l":8,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"Жергілікті максимум әрдайым ғаламдық максимум.","a":false,"e":"Жалған: $x^3-3x$ үшін $x=-1$ жергілікті максимум ($2$), бірақ $x\\to\\infty$ кезінде функция одан үлкен."},{"id":"m4-8-tf2:2","l":8,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"$f$ және $g$ жергілікті максимумы бір нүктеде болса, $f+g$ да сол нүктеде жергілікті максимум.","a":true,"e":"Ақиқат: екеуі де сол нүктенің маңайында ең үлкен мәніне ие, қосындысы да."},{"id":"m4-8-tf2:3","l":8,"lvl":"hard","type":"tf","ctx":"Ойланатын пікірлер. Әр пікірдің ақиқат не жалған екенін негіздеңіз.","q":"Берілген периметрлі тікбұрыштардың ішінде ауданы ең үлкені — шаршы.","a":true,"e":"Ақиқат: $A=x(P/2-x)$, $x=P/4$: екінші қабырға да $P/4$."},{"id":"m4-8-signs:0","l":8,"lvl":"hard","type":"matrix","ctx":"Мәндер кестесі. Ұяшықтарға сандарды жазыңыз.","q":"$f(x)=x^3-3x^2$ үшін $\\begin{pmatrix}f(0)&f(1)\\\\ f(2)&f(3)\\end{pmatrix}$ матрицасын толтырыңыз.","name":"$M=$","a":[[0,-2],[-4,0]]},{"id":"m4-8-can:0","l":8,"lvl":"hard","type":"num","ctx":"Банка. Жауапты ондық бөлшекпен жазыңыз (2 таңбаға дейін).","q":"Көлемі $V=54\\pi$ см³ цилиндрлік банканың бет ауданы ең аз болатын радиусы $r=\\sqrt[3]{V/(2\\pi)}$ неге тең?","a":3},{"id":"m4-8-can:1","l":8,"lvl":"hard","type":"num","ctx":"Банка. Жауапты ондық бөлшекпен жазыңыз (2 таңбаға дейін).","q":"Сол банканың биіктігі $h=V/(\\pi r^2)$ неге тең?","a":6},{"id":"w28-q0","l":8,"lvl":"quiz","type":"choice","q":"f(x) = x³ − 3x² функциясының жергілікті минимумы қай нүктеде?","o":["x = 0","x = 2","x = 1","x = 3"],"a":1,"e":"f' = 3x(x − 2); x = 2 нүктесінде f' таңбасы − тен + ке ауысады, f(2) = −4."},{"id":"w28-q1","l":8,"lvl":"quiz","type":"choice","q":"f(x) = x³ − 3x² функциясының иілу нүктесі қайда?","o":["x = 0","x = 2","x = 3","x = 1"],"a":3,"e":"f'' = 6x − 6 нөлден x = 1 нүктесінде таңба ауыстырады."},{"id":"w28-q2","l":8,"lvl":"quiz","type":"choice","q":"f(x) = x²/(x − 1) графигінің көлбеу асимптотасы қандай?","o":["y = x + 1","y = x","y = 1","y = x − 1"],"a":0,"e":"x²/(x − 1) = x + 1 + 1/(x − 1), қалдық нөлге ұмтылады."},{"id":"w28-q3","l":8,"lvl":"quiz","type":"choice","q":"f(x) = 2x³ − 9x² + 12x функциясының [0; 3] кесіндісіндегі ең үлкен мәні қанша?","o":["5","4","9","0"],"a":2,"e":"f(0) = 0, f(1) = 5, f(2) = 4, f(3) = 9. Ең үлкені кесіндінің ұшында."},{"id":"w28-q4","l":8,"lvl":"quiz","type":"choice","q":"120 м сыммен өзен жағасына тікбұрышты учаске қоршалады (өзен жағы қоршалмайды). Ең үлкен аудан қанша?","o":["900 м²","1800 м²","3600 м²","1200 м²"],"a":1,"e":"A = x(120 − 2x), x = 30, A = 30·60 = 1800."},{"id":"w28-q5","l":8,"lvl":"quiz","type":"choice","q":"f(x) = x⁴ функциясы үшін x = 0 нүктесінде нені білдіреді?","o":["иілу нүктесі","максимум","экстремум жоқ","минимум, бірақ f''(0) = 0"],"a":3,"e":"f' = 4x³ таңбасы − тен + ке ауысады: минимум. Екінші белгі (f''(0) = 0) жауап бермейді."},{"id":"w28-q6","l":8,"lvl":"quiz","type":"choice","q":"Қабырғасы 12 см шаршы қағаздан x қабырғалы бұрыштарды қиып, ашық қорап жасайды. Көлемі ең үлкен болғандағы x қанша?","o":["2 см","3 см","4 см","6 см"],"a":0,"e":"V = x(12 − 2x)², V' = (12 − 2x)(12 − 6x) = 0, x = 2, V = 128."},{"id":"w28-q7","l":8,"lvl":"quiz","type":"choice","q":"Қай пікір дұрыс?","o":["f'(c) = 0 болса, c әрдайым экстремум","f''(c) = 0 болса, c әрдайым иілу нүктесі","Кесіндіде үзіліссіз функцияның ең үлкен мәні ұшында да болуы мүмкін","Жергілікті максимум әрдайым ғаламдық максимум"],"a":2,"e":"Қалған үшеуіне қарсы мысал бар: x³ (нөл), x⁴ (нөл), x³ − 3x (жергілікті максимум ғаламдық емес)."}];
